-- Ejecutar en Supabase -> SQL Editor -> New query -> Run.
-- Requiere 01_esquema.sql (la tabla enemies).
--
-- Enemigos de Honkai: Star Rail: los 375 del juego (version 4.5), divididos en
-- jefes (110) y esbirros (265, de los que 113 son elites).
--
-- Fuentes:
--   Datos del propio juego (TurnBasedGameData, de Dimbreath) -> nombre y
--     descripcion oficiales en espanol, rango, debilidades, resistencias,
--     faccion y habilidades.
--   Nanoka (static.nanoka.cc) -> imagen de cada enemigo.
--
-- Un mismo enemigo aparece en el juego con varias versiones (por dificultad o
-- por contenido) que a veces cambian de debilidades: van juntas en una fila, y
-- las combinaciones distintas quedan en la columna variants.
--
-- Inserta lo que falte y actualiza lo que ya exista, sin borrar nada.
--
-- Generado el 2026-09-15.

--
-- PARTE 3 de 3 (155 filas). El archivo entero no cabia en el SQL Editor:
-- ejecuta las 3 partes, en cualquier orden.

insert into public.enemies (
  id, game_id, name, name_en, category, rank, faction, description, image_url, weaknesses, resistances, variants, skills
)
values
  ('hsr-enemy-1003012', 'honkai-star-rail', 'Teniente Crinargenta (intacto)', 'Silvermane Lieutenant (Complete)', 'esbirro', 'elite', null, 'Una proyección intacta creada por un código alterado. La referencia original es el líder de un escuadrón de la Guardia Crinargenta de Belobog.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_1003010.webp', '["Físico","Hielo","Cuántico"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[{"nombre":"Asalto","descripcion":"Inflige Daño Físico a un aliado.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Perforación","descripcion":"Inflige una gran cantidad de Daño Físico a un aliado.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Reflejo de escudo","descripcion":"Entra en modo contraataque. Tras recibir un ataque de un aliado, su acción se adelanta y usa la habilidad Perforación contra ese objetivo.","tipo":"Habilidad","elemento":null},{"nombre":"Refuerzos","descripcion":"Invoca al Soldado Crinargenta o al Tirador Crinargenta.","tipo":"Habilidad","elemento":null}]'::jsonb),
  ('hsr-enemy-5023020', 'honkai-star-rail', 'Vástago Devorador de Dioses', 'God-Devourer Offspring', 'esbirro', 'elite', 'Fabulae', 'La legión de monstruos que Asat Pramad creó al dividir el poder de la Voracidad es el prototipo de los fabulae actuales. Desde el núcleo aletargado de Ahatopía, percibió el incesante deseo de devorar de la Voracidad. La pulsación de su poder estaba en perfecta sintonía con la Vía de la Destrucción. Esta inquietud le pareció fascinante, por lo que comenzó su propia creación oscura: eliminó las cabezas humanas y dejó unas bocas que ríen y engullen, las cuales rugen, exigen y devoran de forma insaciable al mundo exterior.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_5023020.webp', '["Fuego","Rayo","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, null, '[{"nombre":"Ritual del atracón","descripcion":"Inflige una pequeña cantidad de Daño de Fuego a un aliado y tiene una gran probabilidad de reducir la DEF de ese aliado.","tipo":"Habilidad","elemento":"Fuego"},{"nombre":"Saciedad de ofrendas","descripcion":"Afecta a un personaje aliado con el estado de Devoración, reduce los PV máx. que puede regenerar y roba un porcentaje del ATQ de ese personaje.","tipo":"Habilidad","elemento":null},{"nombre":"Rito de expiación","descripcion":"Cuando se disipa el estado de Devoración infligido por esta unidad, aumenta el ATQ del aliado que disipó el estado de Devoración.","tipo":"Talento","elemento":null},{"nombre":"Festín de bestias","descripcion":"Inflige una pequeña cantidad de Daño de Fuego a todos los aliados.","tipo":"Habilidad","elemento":"Fuego"},{"nombre":"Regurgitación sagrada","descripcion":"Cada vez que recibe un ataque de un aliado, aumentan los PV máx. que pueden regenerar los personajes aliados a los que les haya aplicado el estado Devoración y les devuelve un porcentaje del ATQ. Tras recibir cierta cantidad de ataques de los aliados o cuando se rompe su Debilidad, disipa los estados de Devoración que haya aplicado.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-5023022', 'honkai-star-rail', 'Vástago Devorador de Dioses (error)', 'God-Devourer Offspring (Bug)', 'esbirro', 'elite', 'Fabulae', 'Una proyección falsa creada por un código alterado. La referencia original es el Vástago Devorador de Dioses, la Legión de monstruos que Asat Pramad creó al dividir el poder de la Voracidad, el prototipo de los fabulae actuales. Desde el núcleo aletargado de Ahatopía, percibió el incesante deseo de devorar de la Voracidad. La pulsación de su poder estaba en perfecta sintonía con la Vía de la Destrucción. Esta inquietud le pareció fascinante, por lo que comenzó su propia creación oscura: eliminó las cabezas humanas y dejó unas bocas que ríen y engullen, las cuales rugen, exigen y devoran de forma insaciable al mundo exterior.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_5023020.webp', '["Fuego","Rayo","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, null, '[{"nombre":"Ritual del atracón","descripcion":"Inflige una pequeña cantidad de Daño de Fuego a un aliado y tiene una gran probabilidad de reducir la DEF de ese aliado.","tipo":"Habilidad","elemento":"Fuego"},{"nombre":"Saciedad de ofrendas","descripcion":"Afecta a un personaje aliado con el estado de Devoración, reduce los PV máx. que puede regenerar y roba un porcentaje del ATQ de ese personaje.","tipo":"Habilidad","elemento":null},{"nombre":"Rito de expiación","descripcion":"Cuando se disipa el estado de Devoración infligido por esta unidad, aumenta el ATQ del aliado que disipó el estado de Devoración.","tipo":"Talento","elemento":null},{"nombre":"Festín de bestias","descripcion":"Inflige una pequeña cantidad de Daño de Fuego a todos los aliados.","tipo":"Habilidad","elemento":"Fuego"},{"nombre":"Regurgitación sagrada","descripcion":"Cada vez que recibe un ataque de un aliado, aumentan los PV máx. que pueden regenerar los personajes aliados a los que les haya aplicado el estado Devoración y les devuelve un porcentaje del ATQ. Tras recibir cierta cantidad de ataques de los aliados o cuando se rompe su Debilidad, disipa los estados de Devoración que haya aplicado.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-8012040', 'honkai-star-rail', 'Académico de la Comedia', 'Comediologist', 'esbirro', 'normal', 'Legión Antimateria', 'Creado a partir de una parte escindida del falso Iluminado Asat Pramad, intenta deconstruir por completo la Exultación mediante el análisis de la comedia.
Su existencia nació para destruir la existencia. Toma la tragedia como núcleo de la comedia y la Destrucción como la verdadera esencia de la Exultación.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_8012040.webp', '["Físico","Fuego","Imaginario"]'::jsonb, '[{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, null, '[{"nombre":"Análisis del chiste","descripcion":"Inflige una pequeña cantidad de Daño Cuántico a un aliado.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"Telón final","descripcion":"Al recibir daño letal, aplica Núcleo de la tragedia a los aliados.","tipo":"Talento","elemento":null},{"nombre":"Reunión de humoristas","descripcion":"Añade Reunión de humoristas al orden de acción. Cada vez que Reunión de humoristas actúa, todos los Académicos de la Comedia atacan juntos.","tipo":"Habilidad","elemento":null}]'::jsonb),
  ('hsr-enemy-8011020', 'honkai-star-rail', 'Antibarión', 'Antibaryon', 'esbirro', 'normal', 'Legión Antimateria', 'Para evitar que las antipartículas se diseminaran y se aniquilaran, la Legión Antimateria creó dos tipos de trampas de iones en miniatura para transportarlas y las llamó bariones y antibariones.
Los antibariones poseen una inteligencia básica y los Exploradores del Vacío pueden invocarlos para que despejen su camino en el campo de batalla.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_8011020.webp', '["Físico","Cuántico"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Físico","Cuántico"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Fuego"],"resistencias":[{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Rayo"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Aniquilación","descripcion":"Inflige una pequeña cantidad de Daño Imaginario a un aliado.","tipo":"Habilidad","elemento":"Imaginario"}]'::jsonb),
  ('hsr-enemy-1012020', 'honkai-star-rail', 'Araña Autómata', 'Automaton Spider', 'esbirro', 'normal', 'Jarilo-VI', 'Autómata formado a partir de la tecnología que se conserva del viejo mundo. Sustituye a las personas en los trabajos físicos más básicos.
En el combate, la Araña Autómata es muy inestable y explota cuando recibe daño.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_1012020.webp', '["Rayo","Viento"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Rayo","Viento"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]}]'::jsonb, '[{"nombre":"Colisión","descripcion":"Inflige una pequeña cantidad de Daño Físico a un aliado.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Módulo temporizado","descripcion":"Lanza Módulo autodestructivo en la siguiente acción.","tipo":"Habilidad","elemento":null},{"nombre":"Módulo autodestructivo","descripcion":"Explota e inflige Daño de Fuego a un aliado y a los aliados adyacentes.","tipo":"Habilidad","elemento":"Fuego"},{"nombre":"Cadenas de la destrucción","descripcion":"Tras recibir un golpe letal, inflige Daño de Fuego a los enemigos adyacentes.","tipo":"Talento","elemento":"Fuego"},{"nombre":"Lo█sien█to█ █","descripcion":null,"tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-4032050', 'honkai-star-rail', 'Arco Decrépito de la Marea Oscura', 'Black Tide''s Decrepit Bow', 'esbirro', 'normal', 'Criatura de la marea oscura', 'Una criatura retorcida nacida de la marea oscura. El ansia de matar es la única determinación que queda en su cuerpo hueco.
Lleva un arco con una maldición que le permite disparar en varias direcciones a la vez. Ningún ser vivo que entre en su campo de visión podrá escapar del alcance de sus flechas.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4032050.webp', '["Físico","Hielo","Cuántico"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[{"nombre":"Flecha de la marea maligna","descripcion":"Inflige una pequeña cantidad de Daño Físico a todos los aliados.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Fin predestinado","descripcion":"Cuando un ataque inflige daño a un aliado, una parte de los PV reducidos del objetivo golpeado se convierte en Corrosión.","tipo":"Talento","elemento":null},{"nombre":"Flecha corrosiva","descripcion":"Cuando los PV del objetivo caen por debajo de 0, se disipa su estado de Ruptura de Debilidad y obtiene el efecto de Protección contra Debilidad.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-4012030', 'honkai-star-rail', 'Arquera de la Furia', 'Furiae Archer', 'esbirro', 'normal', 'Titandeudos', 'Una titandeudo esculpida a partir del conflicto e imbuida con la sangre dorada de Nikador. Su fe es tan inamovible como una flecha que va directa a su objetivo y se encarga de encontrar presas para las fuerzas de Kremnos. Caza bestias en las llanuras y enemigos en el campo de batalla, y se asegura de que no sobreviva nada que tenga al alcance.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4012030.webp', '["Hielo","Rayo","Cuántico"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[{"nombre":"Flecha llorosa","descripcion":"Lanza varios ataques comenzando por el lado derecho del equipo aliado y prioriza atacar a todos los aliados 1 vez. Los ataques sobrantes se lanzan contra aliados al azar. Cada ataque inflige una pequeña cantidad de Daño de Rayo. Cuando se vuelve a atacar a un objetivo que ya ha recibido un ataque de esta habilidad, inflige Daño de Rayo extra. Cuando no hay acumulaciones de Armadura de guerra, se reduce la cantidad de ataques de la siguiente vez que se use Flecha llorosa.","tipo":"Habilidad","elemento":"Rayo"},{"nombre":"Protector de la polis","descripcion":"Tiene cierta cantidad de acumulaciones de Armadura de guerra, que reduce el daño que recibe. Tras recibir un ataque, la cantidad de acumulaciones de Armadura de guerra disminuye en 1. Cuando las acumulaciones llegan a 0, Armadura de guerra se destruye, inflige una gran cantidad de Daño Imaginario a esta unidad y retrasa su acción. El aliado que destruye Armadura de guerra recupera energía. Cuando esta unidad es atacada después de que se haya destruido su Armadura de guerra, recibe de forma adicional una pequeña cantidad de Daño Imaginario. Armadura de guerra recupera todas sus acumulaciones cuando termina el turno de esta unidad.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-1002030', 'honkai-star-rail', 'Artillero Crinargenta', 'Silvermane Cannoneer', 'esbirro', 'normal', 'Jarilo-VI', 'Artillero de la Guardia Crinargenta que lleva un cañón portátil a la batalla.
Durante el combate, el Artillero Crinargenta lanza un feroz ataque en cadena a varios objetivos.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_1002030.webp', '["Físico","Hielo","Imaginario"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, '[{"debilidades":["Físico","Hielo","Imaginario"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Físico","Fuego","Imaginario"],"resistencias":[{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Fuego","Cuántico","Imaginario"],"resistencias":[{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Hielo","Cuántico"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Fuego","Hielo"],"resistencias":[{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Físico","Hielo","Rayo"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Hielo","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]}]'::jsonb, '[{"nombre":"Cortina de fuego","descripcion":"Inflige una pequeña cantidad de Daño Físico a un aliado y a los aliados adyacentes.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Yo te cubro","descripcion":"Proporciona refuerzos a un enemigo determinado y lanza un ataque adicional cuando ese enemigo ataca a los aliados. Inflige una pequeña cantidad de Daño Físico a un aliado y a los aliados adyacentes.","tipo":"Habilidad","elemento":null}]'::jsonb),
  ('hsr-enemy-4032028', 'honkai-star-rail', 'Asesino del Tiempo', 'Time Assassin', 'esbirro', 'normal', null, 'Asesino del Tiempo que viaja a través del tiempo y cosecha sin piedad el valioso valor de acción de la gente.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4032020.webp', '["Hielo","Rayo","Cuántico"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[{"nombre":"Ofrenda conjunta: Nubarrón de la fatalidad","descripcion":"Inflige una pequeña cantidad de Daño Físico a un aliado y a los objetivos adyacentes.","tipo":"Habilidad","elemento":null},{"nombre":"Ofrenda conjunta: Final del destino","descripcion":"Inflige una pequeña cantidad de Daño Físico a todos los aliados. Una parte de los PV reducidos de los objetivos golpeados se convierte en Corrosión.","tipo":"Habilidad","elemento":null},{"nombre":"Reza por mí","descripcion":"Resiste los estados negativos de Control. Cuando Rey Demonio de la Capa Bruna vuelve a lanzar Nubarrón de la fatalidad o Final del destino, si fue invocado por este ataque y está en el estado de Ofrenda conjunta, ataca junto a Rey Demonio de la Capa Bruna. Luego esta unidad es absorbida por Rey Demonio de la Capa Bruna, con lo que este regenera los PV que fueron convertidos en Enredo agónico y obtiene Poder del desastre.","tipo":"Talento","elemento":null},{"nombre":"Brinda por mí","descripcion":"Al recibir un golpe letal mientras se encuentra en el estado de Grillete, si Rey Demonio de la Capa Bruna no tiene 0 acumulaciones de Poder del desastre, esta unidad es invocada de nuevo por él y entra en el estado de Grillete, pero a cambio Rey Demonio de la Capa Bruna pierde 1 acumulación de Poder del desastre y cierta proporción de PV. Cuando Rey Demonio de la Capa Bruna lanza Abandono sin lágrimas, absorbe a esta unidad y regenera los PV que se habían convertido en Enredo agónico.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-3002011', 'honkai-star-rail', 'Bananadjunto de la Oficina Platanoacadémica', 'Banacademic Office''s Assistanana', 'esbirro', 'normal', 'Compañía Teatral de Terrores', 'Originalmente, un Sr. Pantallarredonda equipado con material académico general, pero el virus memético lo infectó y este se convirtió en material bananacadémico. Cambia entre un estado de ánimo soleado como un plátano en sazón u oscuro cual plátano pasado. Este simio es un compañero de trabajo digno de ser bananapreciado.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_3002011.webp', '["Hielo","Rayo","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, '[{"debilidades":["Hielo","Rayo","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Hielo","Rayo","Imaginario"],"resistencias":[{"elemento":"Físico","valor":40},{"elemento":"Fuego","valor":40},{"elemento":"Viento","valor":40},{"elemento":"Cuántico","valor":40}]}]'::jsonb, '[{"nombre":"Vacaciones platánicas","descripcion":"Recupera energía para un aliado. Esta habilidad solo se puede usar en el estado Canal del descanso.","tipo":"Habilidad","elemento":null},{"nombre":"Semestre platagónico","descripcion":"Inflige una pequeña cantidad de Daño Cuántico a todos los aliados y reduce la energía de todos los objetivos. Esta habilidad solo se puede usar en el estado Canal de la clase.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"Cambio del bananatemario","descripcion":"Cambia el estado Canal del descanso al estado Canal de la clase.","tipo":"Habilidad","elemento":null},{"nombre":"Desorden del bananatemario","descripcion":"Tras recibir un ataque, cambia el estado Canal de la clase al estado Canal del descanso. Cuando se encuentra en el estado Canal del descanso, no cambia tras recibir un ataque.","tipo":"Talento","elemento":null},{"nombre":"Platanouso apropiado","descripcion":"Al cambiar del estado Canal de la clase al estado Canal del descanso, un aliado al azar recupera energía.","tipo":"Talento","elemento":null},{"nombre":"Incidente bananacadémico","descripcion":"Tras recibir cierta cantidad de ataques, cambia el estado Canal de la clase al estado Canal del descanso y es afectado con Ruptura de Debilidad.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-3002013', 'honkai-star-rail', 'Bananadjunto de la Oficina Platanoacadémica (intacto)', 'Banacademic Office''s Assistanana (Complete)', 'esbirro', 'normal', null, 'Una proyección intacta creada por un código alterado. La referencia original es un Sr. Pantallarredonda equipado con material académico general, pero el virus memético lo infectó y este se convirtió en material bananacadémico. Cambia entre un estado de ánimo soleado como un plátano en sazón u oscuro cual plátano pasado. Este simio es un compañero de trabajo digno de ser bananapreciado.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_3002011.webp', '["Hielo","Rayo","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":40},{"elemento":"Fuego","valor":40},{"elemento":"Viento","valor":40},{"elemento":"Cuántico","valor":40}]'::jsonb, null, '[{"nombre":"Platanouso apropiado","descripcion":"Recupera energía para un aliado al azar y reduce la Firmeza de Personal Platanoacadémico del Veleibosque (intacto). Esta habilidad solo se puede usar en el estado Canal del descanso.","tipo":"Talento","elemento":null},{"nombre":"Semestre platagónico","descripcion":"Inflige una pequeña cantidad de Daño Cuántico a todos los aliados y reduce la energía de todos los objetivos. Esta habilidad solo se puede usar en el estado Canal de la clase.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"Cambio del bananatemario","descripcion":"Cambia el estado Canal del descanso al estado Canal de la clase.","tipo":"Habilidad","elemento":null},{"nombre":"Incidente bananacadémico","descripcion":"Tras recibir cierta cantidad de ataques, cambia el estado Canal de la clase al estado Canal del descanso.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-8011010', 'honkai-star-rail', 'Barión', 'Baryon', 'esbirro', 'normal', 'Legión Antimateria', 'Para evitar que las antipartículas se diseminaran y se aniquilaran, la Legión Antimateria creó dos tipos de trampas de iones en miniatura para transportarlas y las llamó bariones y antibariones.
Los bariones poseen una inteligencia básica y los Exploradores del Vacío pueden invocarlos para que despejen su camino en el campo de batalla.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_8011010.webp', '["Hielo","Viento"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Hielo","Viento"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Viento"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Aniquilación","descripcion":"Inflige una pequeña cantidad de Daño Cuántico a un aliado.","tipo":"Habilidad","elemento":"Cuántico"}]'::jsonb),
  ('hsr-enemy-4012050', 'honkai-star-rail', 'Bartholos, el Espirizuelo', '"Spirithief" Bartholos', 'esbirro', 'normal', 'Titandeudos', 'Espíritus que vagan por los campos y los callejones de Amphoreus. Les gusta robar y burlarse de los viajeros. A menudo se adelantan a los cazadores de tesoros en el último momento y, como broma inofensiva, les dejan solamente una moneda.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4012050.webp', '[]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[{"nombre":"Acertijo con doble sentido","descripcion":"Bartholos propone un acertijo y entra en el estado de Acertijo. Los aliados pueden responder lanzando el ATQ básico, la habilidad básica o la habilidad definitiva.","tipo":"Habilidad","elemento":null},{"nombre":"Explicación en bucle","descripcion":"Tras usar el ataque correcto para responder al acertijo de Bartholos, este cambiará el acertijo inmediatamente y se infligirá un Daño Físico equivalente a un porcentaje de sus PV máx. Cuando Bartholos abandona la batalla, aumenta el daño que infligen todos los aliados.","tipo":"Talento","elemento":null},{"nombre":"Respuesta críptica","descripcion":"Establecido inicialmente como objetivo de fila trasera.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-8001031', 'honkai-star-rail', 'Bola de Fuerza Prestada', 'Borrowed Force', 'esbirro', 'normal', null, 'Orbes mágicos invocados por el vínculo de ATQ AdE. Pueden ser atacados.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_8001030.webp', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb),
  ('hsr-enemy-1012040', 'honkai-star-rail', 'Brazo Robótico Auxiliar', 'Auxiliary Robot Arm Unit', 'esbirro', 'normal', null, 'Dispositivo mecánico que controla Svarog.
El brazo robótico ataca violentamente a tu equipo si permanece en el campo de batalla durante cierto número de turnos.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_1012040.webp', '["Rayo","Viento","Cuántico"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[{"nombre":"Abrazo opresivo","descripcion":"Inflige un Daño Físico basado en un porcentaje de los PV máx. a los aliados afectados por Confinamiento.","tipo":"Talento","elemento":"Físico"},{"nombre":"A la espera","descripcion":null,"tipo":"Habilidad","elemento":null},{"nombre":"Campo eléctrico desactivado","descripcion":"Inflige un Daño Físico basado en un porcentaje de los PV máx. a los aliados afectados por Confinamiento.","tipo":"Habilidad","elemento":null},{"nombre":"Explosión controlada","descripcion":"El Brazo Robótico Auxiliar explota e inflige una gran cantidad de Daño Físico a un aliado.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Aviso de sobrecarga","descripcion":"El Brazo Robótico Auxiliar entra en estado de Sobrecarga y disipa inmediatamente el Confinamiento de los aliados. Tras entrar en este estado, el Brazo Robótico Auxiliar activa Explosión controlada en su siguiente acción.","tipo":"Habilidad","elemento":null}]'::jsonb),
  ('hsr-enemy-4012070', 'honkai-star-rail', 'Brazolargo del Pesar', 'The Long Arms of Sorrow', 'esbirro', 'normal', null, 'Todos los que intenten escapar del final deben enfrentarse a la persecución del inframundo.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4012070.webp', '["Rayo","Cuántico","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20}]'::jsonb, '[{"debilidades":["Rayo","Cuántico","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20}]},{"debilidades":["Rayo","Viento","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Viento","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Hielo","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Los vivos no escaparán","descripcion":"Inflige una pequeña cantidad de Daño Cuántico a un aliado.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"Los muertos no se evadirán","descripcion":"Inflige una pequeña cantidad de Daño Cuántico a un aliado y a los objetivos adyacentes. Si el objetivo tiene un porcentaje de PV superior a cierta cantidad, el daño se convierte en Daño de atrofia de tipo Cuántico.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"Entre la vida y la muerte","descripcion":"En el estado de Obituario demorado, Los vivos no escaparán se potencia a Los muertos no se evadirán.","tipo":"Talento","elemento":null},{"nombre":"Florecimiento mortal","descripcion":"Cuando el Guía del Marchitamiento y la Podredumbre está en el estado de Fragancia de la muerte, Los vivos no escaparán de Brazolargo del Pesar se potencia a Los muertos no se evadirán. Al derrotar a Brazolargo del Pesar, se reduce la Firmeza y los PV de Guía del Marchitamiento y la Podredumbre. Si Guía del Marchitamiento y la Podredumbre se encuentra en el estado de Fragancia de la muerte en ese momento, todos los aliados regeneran PV adicionales.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-2032040', 'honkai-star-rail', 'Cabeza Devoradora de Nebulosas', 'Nebula Devourer', 'esbirro', 'normal', null, 'Cabeza de la bestia interior, bebedora de la luz estelar, devoradora de nebulosas.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/BossIconTemporary.webp', '["Fuego","Viento","Cuántico"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Fuego","Viento","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Fuego","Viento","Cuántico"],"resistencias":[{"elemento":"Hielo","valor":40},{"elemento":"Rayo","valor":40},{"elemento":"Imaginario","valor":40}]}]'::jsonb, '[{"nombre":"Devoración de nebulosas","descripcion":"Inflige una pequeña cantidad de Daño de Viento a todos los aliados.","tipo":"Habilidad","elemento":"Viento"},{"nombre":"Respiración de éter","descripcion":"Se lanza en el estado de Resonancia. Inflige Daño de Viento a todos los aliados y tiene una gran probabilidad de afectarlos con Cólera.","tipo":"Habilidad","elemento":"Viento"},{"nombre":"Salvaguardia","descripcion":"Entra en el estado de Salvaguardia y reduce el daño que recibe cuando no se ha roto su Debilidad. Al romperse su Debilidad, su acción se retrasa adicionalmente y el daño que recibe después aumenta.","tipo":"Habilidad","elemento":null}]'::jsonb),
  ('hsr-enemy-3002030', 'honkai-star-rail', 'Cánido Burbujeante de la Compañía Teatral de Terrores', 'Dreamjolt Troupe''s Bubble Hound', 'esbirro', 'normal', 'Compañía Teatral de Terrores', 'Máquina de servicio de Colonipenal que perdió el control debido a las interferencias emocionales en el paisaje onírico.
Era un robot repartidor de FelizAlma y, tras perder el control, continúa dispensando dulzura e invitando a todo el mundo a probar esta delicia.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_3002030.webp', '["Físico","Rayo","Viento"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Físico","Rayo","Viento"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Rayo","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Hielo","Rayo","Cuántico","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Viento","valor":20}]},{"debilidades":["Físico","Fuego","Hielo","Rayo","Viento","Cuántico","Imaginario"],"resistencias":[]},{"debilidades":["Físico","Fuego","Hielo","Rayo"],"resistencias":[{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Viento","Cuántico","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20}]}]'::jsonb, '[{"nombre":"Invitación a beber","descripcion":"Inflige Daño Físico a un aliado.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Libación de dulzura","descripcion":"Al recibir un golpe letal, inflige Daño Físico a los enemigos adyacentes, aumenta la VEL de estos y les inflige Sangrado.","tipo":"Talento","elemento":null},{"nombre":"Gran jolgorio","descripcion":"Al recibir un ataque o Daño con el tiempo, obtiene una acumulación de Embriaguez de FelizAlma. Cada acumulación aumenta el daño infligido.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-8002070', 'honkai-star-rail', 'Chanchito de la Abundancia', 'Trotter of Abundance', 'esbirro', 'normal', null, 'Criatura interdimensional perdida entre las estrellas. Tiene buen carácter y un sabor dulce, pero no se puede comer. Pasa la mayor parte de su vida alimentándose y huyendo. Los viajeros que se lo encuentran lo consideran un presagio de buena suerte.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_8002050.webp', '["Físico","Rayo","Cuántico"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[{"nombre":"Qué... ¡qué miedo!","descripcion":"El Chanchito se asustó y huirá dentro de 2 turnos.","tipo":"Habilidad","elemento":null},{"nombre":"¡Corre, Chanchito, corre!","descripcion":"El Chanchito está aterrorizado y huirá dentro de 1 turno.","tipo":"Habilidad","elemento":null},{"nombre":"¡Uf, salvado!","descripcion":"El Chanchito huyó y desapareció sin dejar rastro.","tipo":"Habilidad","elemento":null},{"nombre":"¡Yo... te curaré!","descripcion":"Cuando un enemigo que no sea el Chanchito de la Abundancia recibe un ataque de un aliado, consume sus PV y regenera los PV del objetivo atacado.","tipo":"Talento","elemento":null}]'::jsonb),
