  ('hsr-enemy-2032060', 'honkai-star-rail', 'Cola Purgadora de Mundos', 'Worldpurge Tail', 'esbirro', 'normal', null, 'Cola de la bestia interior, invocadora de tormentas, purgadora de mundos mortales.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/BossIconTemporary.webp', '["Físico","Cuántico"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Físico","Cuántico"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Rayo","Viento","Cuántico"],"resistencias":[{"elemento":"Fuego","valor":40},{"elemento":"Hielo","valor":40},{"elemento":"Imaginario","valor":40}]}]'::jsonb, '[{"nombre":"Purga de mundos","descripcion":"Inflige una pequeña cantidad de Daño de Viento a todos los aliados.","tipo":"Habilidad","elemento":"Viento"},{"nombre":"Exterminio de mundos mortales","descripcion":"Se lanza en el estado de Resonancia. Inflige Daño de Viento a todos los aliados y tiene una gran probabilidad de afectarlos con Debilitación.","tipo":"Habilidad","elemento":"Viento"},{"nombre":"Salvaguardia","descripcion":"Entra en el estado de Salvaguardia y reduce el daño que recibe cuando no se ha roto su Debilidad. Al romperse su Debilidad, su acción se retrasa adicionalmente y el daño que recibe después aumenta.","tipo":"Habilidad","elemento":null}]'::jsonb),
  ('hsr-enemy-4012060', 'honkai-star-rail', 'Conquistar o Ser Conquistado', 'Conquer or Be Conquered', 'esbirro', 'normal', null, 'La punta de su lanza dibuja una frontera que no tiene límites.
Los soldados y los civiles que están dentro de la frontera se marcan como conquistador o por conquistar.
La sangre de los temerosos se convierte en hidromiel para el cuerpo divino, y las almas de los desafiantes entran en el palacio glorioso bajo el río Estigia.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4012060.webp', '["Rayo","Cuántico","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20}]'::jsonb, '[{"debilidades":["Rayo","Cuántico","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20}]},{"debilidades":["Físico","Fuego","Viento","Cuántico"],"resistencias":[{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Tirano de los derrotados","descripcion":"Conquistar o Ser Conquistado no puede actuar.","tipo":"Talento","elemento":null},{"nombre":"Poseedor de todas las heridas","descripcion":"Al recibir un ataque de un objetivo con el estado Conquistado correspondiente, el daño recibido aumenta en gran medida. Al recibir un golpe letal, se consumen PV de Otorgador, Capitán de Legiones: Lanza de la Furia.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-4032040', 'honkai-star-rail', 'Consejero de la Marea Oscura', 'Black Tide Council', 'esbirro', 'normal', 'Criatura de la marea oscura', 'Una creación retorcida nacida de la marea oscura. Su sed de matar se ha convertido en la única voluntad que queda de su cuerpo vacío.
Conocimientos que en otro tiempo pudieron servir a la humanidad se han vuelto ahora contra la civilización. Maestros del acecho y la estrategia, se ciernen como buitres hambrientos, ansiosos por ofrecer nuevos sacrificios a la marea negra.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4032040.webp', '["Fuego","Rayo","Viento"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[{"nombre":"Ocultamiento","descripcion":"Entra en el estado de Ocultamiento.","tipo":"Habilidad","elemento":null},{"nombre":"Razón destruida","descripcion":"Inflige una pequeña cantidad de Daño Físico a un aliado.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Agitación insidiosa","descripcion":"Inflige Daño Físico a un aliado y disipa el estado de Ocultamiento. Solo se puede lanzar durante el estado de Ocultamiento.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Punto débil","descripcion":"Cuando está en el estado de Ocultamiento, el daño recibido aumenta. Si Ocultamiento se disipa por haberse roto su Debilidad, su acción se retrasa y el efecto de Vulnerabilidad dura hasta el comienzo de su siguiente acción.","tipo":"Talento","elemento":null},{"nombre":"Carne ennegrecida","descripcion":"Cuando los PV del objetivo caen por debajo de 0, se disipan los estados negativos de Control y el estado de Ruptura de Debilidad de esta unidad y obtiene el efecto de Protección contra Debilidad. Además, lanza Ocultamiento.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-4012040', 'honkai-star-rail', 'Coro de la Furia', 'Furiae Troupe', 'esbirro', 'normal', 'Titandeudos', 'Un titandeudo esculpido a partir del conflicto e imbuido con la sangre dorada de Nikador. Cantante a las órdenes de la Lanza de la Furia. En sus letras canta alabanzas a los soldados y al rey loco y utiliza conjuros para implorar la bendición de Nikador.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4012040.webp', '["Físico","Hielo","Imaginario"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, '[{"debilidades":["Físico","Hielo","Imaginario"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Físico","Rayo","Viento"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Rayo","Imaginario"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]}]'::jsonb, '[{"nombre":"Loa a Nikador","descripcion":"Entra en el estado Cántico de batalla y aumenta el límite de acumulaciones de Armadura de guerra de los demás enemigos (sin incluir esta unidad). Al entrar en combate, entra inmediatamente en el estado Cántico de batalla.","tipo":"Habilidad","elemento":null},{"nombre":"Al dúctil fuego","descripcion":"Inflige Daño Imaginario a un aliado determinado y a los objetivos adyacentes.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"Protector de la polis","descripcion":"Tiene cierta cantidad de acumulaciones de Armadura de guerra, que reduce el daño que recibe. Tras recibir un ataque, la cantidad de acumulaciones de Armadura de guerra disminuye en 1. Cuando las acumulaciones llegan a 0, Armadura de guerra se destruye, inflige una gran cantidad de Daño Imaginario a esta unidad y retrasa su acción. El aliado que destruye Armadura de guerra recupera energía. Cuando esta unidad es atacada después de que se haya destruido su Armadura de guerra, recibe de forma adicional una pequeña cantidad de Daño Imaginario. Armadura de guerra recupera todas sus acumulaciones cuando termina el turno de esta unidad.","tipo":"Talento","elemento":null},{"nombre":"Los guerreros no volverán a caer","descripcion":"Regenera el Contador de PV de un enemigo.","tipo":"Habilidad","elemento":null}]'::jsonb),
  ('hsr-enemy-4052020', 'honkai-star-rail', 'Cría de Ilusión Vacía', 'Mirage Fizzle Kid', 'esbirro', 'normal', 'Sirena abisal', 'Las hijas del mar, con su carne y espíritu corroídos por los pecados de la Destrucción, solo conservan una cáscara vacía y retorcida... En esta vida siguieron la afilada hoja del Océano y no se desvanecieron en la nihilidad, sino que se convirtieron en olas gigantes que arremeten contra el sol negro.
La tormenta apocalíptica cae del cielo, proclamando la extinción de todas las cosas.
¡Oh, ilusión vacía y prematura!, condenada a perecer antes de haber nacido, exhalando interminables lamentos.
El turbio líquido amniótico fluye, tiñendo de negro el cielo y la tierra, manchando incluso la esperanza recién nacida.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4052020.webp', '["Fuego","Rayo"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[{"nombre":"Rumia de sueños putrefactos","descripcion":"Inflige una pequeña cantidad de Daño Cuántico a un aliado. Si en el campo de batalla hay una Cría de Ilusión Vacía en el estado Asalto al espejismo, inflige adicionalmente Daño Cuántico.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"Asalto al espejismo","descripcion":"Entra en el estado Asalto al espejismo y fija como objetivo a un aliado. Mientras el estado permanezca activo, otras Crías de Ilusión Vacía priorizarán atacar al objetivo fijado. El estado Asalto al espejismo se disipa cuando se rompe la Debilidad de esta unidad o recibe un golpe letal.","tipo":"Habilidad","elemento":null},{"nombre":"Tal es el destino de las burbujas","descripcion":"Al recibir un golpe letal, inflige Daño Cuántico a los enemigos adyacentes a esta unidad.","tipo":"Talento","elemento":null},{"nombre":"Descanso en el agua","descripcion":"Después de recibir cierta cantidad de ataques con el ATQ básico, la habilidad básica, la habilidad definitiva o la habilidad de mnemoduende, su acción se adelanta. Cuando se encuentra en el estado de Disfrute destructivo, se reduce la cantidad de ataques necesarios para activar la Acción adelantada.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-3001010', 'honkai-star-rail', 'Crupier de la Compañía Teatral de Terrores', 'Dreamjolt Troupe''s Spring Loader', 'esbirro', 'normal', 'Compañía Teatral de Terrores', 'Máquina de servicio de Colonipenal que perdió el control debido a las interferencias emocionales en el paisaje onírico.
Antes era una herramienta de entretenimiento en la mesa de juego y, tras perder el control, sigue agitando los dados que sostiene en la mano y continúa el juego de una forma cruda.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_3001010.webp', '["Físico","Viento"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Físico","Viento"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Rayo"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Hielo"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Lanzamiento de dados","descripcion":"Inflige una pequeña cantidad de Daño Físico a un aliado y tiene cierta probabilidad de reducir la RES a efecto de ese aliado.","tipo":"Habilidad","elemento":"Físico"}]'::jsonb),
  ('hsr-enemy-3002050', 'honkai-star-rail', 'Cubo de Basura Señorial', 'Lordly Trashcan', 'esbirro', 'normal', 'Cosmos', 'Una criatura peculiar nacida en el campo de la ficción. Su historia se ha documentado en crónicas sin nombre: un valiente y solitario cubo a quien el rey de la basura encomienda la misión de buscar guerreros formidables para eliminar los residuos que amenazan al mundo.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_3002050.webp', '[]'::jsonb, '[]'::jsonb, null, '[{"nombre":"Las pruebas del cubo","descripcion":"Inflige Daño Físico a un aliado.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Las tribulaciones del cubo","descripcion":"Aumenta su ATQ. Este efecto se puede acumular y no se puede eliminar.","tipo":"Habilidad","elemento":null},{"nombre":"El credo del cubo","descripcion":"Cuando se rompe su Debilidad, abandona la batalla. Cuando recibe un ataque de los aliados, se implanta la Debilidad correspondiente al tipo del ataque recibido. Se pueden implantar hasta 2 Debilidades.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-3002051', 'honkai-star-rail', 'Cubo de Basura Señorial (proyección)', 'Lordly Trashcan (Projection)', 'esbirro', 'normal', null, 'Una criatura peculiar nacida en el campo de la ficción. Su historia se ha documentado en crónicas sin nombre: un valiente y solitario cubo a quien el rey de la basura encomienda la misión de buscar guerreros formidables para eliminar los residuos que amenazan al mundo.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_3002050.webp', '[]'::jsonb, '[]'::jsonb, null, '[{"nombre":"Las pruebas del cubo","descripcion":"Inflige Daño Físico a un aliado.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Las tribulaciones del cubo","descripcion":"Aumenta su ATQ. Este efecto se puede acumular y no se puede eliminar.","tipo":"Habilidad","elemento":null},{"nombre":"El credo del cubo","descripcion":"Cuando se rompe su Debilidad, se rompe la Debilidad de todos los enemigos, excepto Cubo de Basura Señorial (proyección) y esta unidad abandona la batalla. Cuando recibe un ataque, se implanta la Debilidad correspondiente al tipo del ataque recibido.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-4012080', 'honkai-star-rail', 'Cuervo del Trueno Solar', 'Daythunder Raven', 'esbirro', 'normal', null, 'Bandada de cuervos que revolotea alrededor de la Divinidad de la Síntesis. Tiene el poder de polarizar el clima. Si no se controla adecuadamente, puede ser muy peligrosa.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4012080.webp', '["Físico","Viento","Cuántico"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[{"nombre":"Descarga eléctrica","descripcion":"Inflige una pequeña cantidad de Daño de Rayo a un aliado.","tipo":"Habilidad","elemento":"Rayo"},{"nombre":"Calentón","descripcion":"Aumenta la Temperatura actual. Cuando se rompe su Debilidad, disminuye la Temperatura actual.","tipo":"Habilidad","elemento":null},{"nombre":"Polarización","descripcion":"Aumenta la cantidad de Tempestanimbos. Cuando se rompe su Debilidad, disminuye la cantidad de Tempestanimbos.","tipo":"Habilidad","elemento":null}]'::jsonb),
  ('hsr-enemy-2022020', 'honkai-star-rail', 'Discípulo de Sanctus Medicus: Alquimista Interno', 'Disciples of Sanctus Medicus: Internal Alchemist', 'esbirro', 'normal', 'El Luofu de Xianzhou', 'Un miembro secreto de los Discípulos de Sanctus Medicus que se ha infiltrado en el Luofu de Xianzhou.
Buscan la iluminación a través de la medicina y practican la introspección a través de los elixires. Ansían revivir las artes perdidas de la Abundancia para llevar a la gente de Xianzhou a la siguiente etapa de su evolución.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_2022020.webp', '["Físico","Imaginario"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":40},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, '[{"debilidades":["Físico","Imaginario"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":40},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Físico","Cuántico"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":40},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":40},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":40},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]}]'::jsonb, '[{"nombre":"Núcleo de plantación","descripcion":"Inflige Provocación de la centella a un aliado.","tipo":"Habilidad","elemento":null},{"nombre":"Lacayo del trueno","descripcion":"Inflige una pequeña cantidad de Daño de Rayo a un aliado.","tipo":"Habilidad","elemento":"Rayo"},{"nombre":"Ruptura de núcleo","descripcion":"Al recibir un golpe letal, inflige Daño de Rayo a todos los aliados a los que haya aplicado Provocación de la centella y disipa este estado de los objetivos golpeados.","tipo":"Talento","elemento":"Rayo"}]'::jsonb),
  ('hsr-enemy-2022060', 'honkai-star-rail', 'Discípulo de Sanctus Medicus: Ballistarius', 'Disciples of Sanctus Medicus: Ballistarius', 'esbirro', 'normal', 'El Luofu de Xianzhou', 'Un miembro secreto de los Discípulos de Sanctus Medicus que se ha infiltrado en el Luofu de Xianzhou.
Se funden con su arma. Ansían revivir las artes perdidas de la Abundancia para llevar a la gente de Xianzhou a la siguiente etapa de su evolución.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_2022060.webp', '["Físico","Hielo","Viento"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Físico","Hielo","Viento"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Fuego","Cuántico"],"resistencias":[{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Hielo","Rayo","Viento"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Ballesta afilada","descripcion":"Inflige continuamente Daño de Rayo a aliados al azar.","tipo":"Habilidad","elemento":"Rayo"}]'::jsonb),
  ('hsr-enemy-8012020', 'honkai-star-rail', 'Distorsionador del Vacío', 'Voidranger: Distorter', 'esbirro', 'normal', 'Legión Antimateria', 'Explorador del Vacío que sobrevivió a los efectos de la aniquilación. Tiene un extraño equilibrio de partículas positivas y negativas en su cuerpo y posee un poder más especial que el del Saqueador del Vacío.
Son las unidades básicas de la Legión Antimateria. Poseen cierta inteligencia y pueden controlar a los Saqueadores de una pequeña área adyacente.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_8012020.webp', '["Viento","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, '[{"debilidades":["Viento","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Físico","Hielo","Imaginario"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Fuego","Hielo"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Orden de la Nihilidad","descripcion":"Fija como objetivo a un aliado para que todos los enemigos lo ataquen.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"Ataque del vacío sin sombra","descripcion":"Inflige Daño Cuántico a un aliado.","tipo":"Habilidad","elemento":"Cuántico"}]'::jsonb),
  ('hsr-enemy-3022010', 'honkai-star-rail', 'Eco de Sueños Pasados', 'Echo of Faded Dreams', 'esbirro', 'normal', null, 'Los ecos de los recuerdos que alguien tenía sobre su amada familia. Son su compañía en las largas noches del pasado, del presente y del futuro eterno.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_3022010.webp', '["Fuego","Rayo","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, '[{"debilidades":["Fuego","Rayo","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Fuego","Rayo","Cuántico","Imaginario"],"resistencias":[{"elemento":"Físico","valor":40},{"elemento":"Hielo","valor":40},{"elemento":"Viento","valor":40}]}]'::jsonb, '[{"nombre":"Afflitto","descripcion":"Inflige una pequeña cantidad de Daño Imaginario a un aliado y retrasa ligeramente su acción.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"Come In Incubo","descripcion":"Todo el daño recibido se pasará a Coro Armonioso en su lugar.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-4012061', 'honkai-star-rail', 'El Conquistado', 'The Conquered', 'esbirro', 'normal', null, 'La punta de su lanza dibuja una frontera que no tiene límites.
Los soldados y los civiles que están dentro de la frontera se marcan como conquistador o por conquistar.
La sangre de los temerosos se convierte en hidromiel para el cuerpo divino, y las almas de los desafiantes entran en el palacio glorioso bajo el río Estigia.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4012060.webp', '["Fuego","Rayo","Cuántico","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20}]'::jsonb, null, '[{"nombre":"Victoria sobre billones de huesos","descripcion":"El Conquistado no puede actuar. Al ser invocado, obtiene Armadura de guerra o Armadura de guerra refinada según la fase en la que se encuentre Ejército Triunfante Destrozado por la Guerra.","tipo":"Talento","elemento":null},{"nombre":"Hogar tras miles de cicatrices","descripcion":"Cuando El Conquistado recibe un golpe letal, si Armadura de guerra o Armadura de guerra refinada no han sido destruidas, obtiene directamente los pts. de habilidad básica correspondientes y Gloria. Al recibir un golpe letal, se reduce la Firmeza y los PV de Ejército Triunfante Destrozado por la Guerra.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-3021040', 'honkai-star-rail', 'El Escudo', '"The Shield"', 'esbirro', 'normal', null, 'Una estatua del Escudo. La Lanza y El Escudo rodean el Alma de la Belleza y son interdependientes. El Escudo representa la determinación de defender a los vivos.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_3021040.webp', '["Físico","Rayo"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Físico","Rayo"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Rayo"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Diadema del auxilio","descripcion":"Aplica una barrera al enemigo Argenti. Aplica barreras a todos los enemigos mientras se encuentra en el estado Alma libre.","tipo":"Habilidad","elemento":null},{"nombre":"Imitación del deseo veloz","descripcion":"Al recibir un golpe letal, aplica una barrera al atacante. Aplica barreras a todos los aliados mientras se encuentra en el estado Alma libre.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-8012030', 'honkai-star-rail', 'Eliminador del Vacío', 'Voidranger: Eliminator', 'esbirro', 'normal', 'Legión Antimateria', 'Restos de un cuerpo que sufrió la corrosión del Fragmentum después de su muerte. Aunque sus constantes vitales experimentaron un cambio, sigue llevando a cabo sus órdenes de eliminación.
El Eliminador del Vacío deja una marca en el objetivo que golpea para que reciba daño extra con sus ataques.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_8012030.webp', '["Fuego","Hielo","Cuántico"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Fuego","Hielo","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Hielo"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Cañón del vacío","descripcion":"Inflige Daño Imaginario a un aliado y entra en el estado de Saturación. El aliado que recibe el ataque tiene cierta probabilidad de ser afectado con Explosión.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"Barrera térmica","descripcion":"Disipa su estado de Saturación.","tipo":"Habilidad","elemento":null}]'::jsonb),
  ('hsr-enemy-1012032', 'honkai-star-rail', 'Emperador Ámbar', 'Amber King', 'esbirro', 'normal', null, 'Invencible... No hay otra forma de describirlo.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_1012030.webp', '["Rayo","Viento","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, null, '[{"nombre":"Asalto Ámbar","descripcion":"Inflige Daño Físico a un aliado.","tipo":"Habilidad","elemento":"Físico"}]'::jsonb),
  ('hsr-enemy-8001040', 'honkai-star-rail', 'Engendro Eléctrico', 'Thunderspawn', 'esbirro', 'normal', 'Monstruos del Fragmentum', 'Elemento cristalizado con una inteligencia muy simple. Flota en el Fragmentum en forma de pájaro que emite chispas eléctricas y emite truenos.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_8001040.webp', '["Físico","Viento"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":40},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[{"nombre":"Destello repentino","descripcion":"Inflige una pequeña cantidad de Daño de Rayo a un aliado y tiene una gran probabilidad de causarle Electrocución.","tipo":"Habilidad","elemento":"Rayo"}]'::jsonb),
  ('hsr-enemy-8001020', 'honkai-star-rail', 'Engendro Escarchado', 'Frostspawn', 'esbirro', 'normal', 'Monstruos del Fragmentum', 'Elemento cristalizado con una inteligencia muy simple. Flota en el Fragmentum en forma de pájaro que emite un frío intenso y que congela todo lo que le rodea.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_8001020.webp', '["Fuego","Viento"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":40},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Fuego","Viento"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":40},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Rayo","Viento"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":40},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":40},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Fuego","Viento"],"resistencias":[{"elemento":"Hielo","valor":40},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Perturbación","descripcion":"Inflige una pequeña cantidad de Daño de Hielo a un aliado.","tipo":"Habilidad","elemento":"Hielo"}]'::jsonb),
  ('hsr-enemy-8001050', 'honkai-star-rail', 'Engendro Huracanado', 'Windspawn', 'esbirro', 'normal', 'Monstruos del Fragmentum', 'Elemento cristalizado con una inteligencia muy simple. Flota en el Fragmentum en forma de pájaro envuelto por corrientes de aire que avanza como un tornado.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_8001050.webp', '["Fuego","Rayo"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":40},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Fuego","Rayo"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":40},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Imaginario"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":40},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Fuego","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":40},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Colores en el viento","descripcion":"Inflige una pequeña cantidad de Daño de Viento a un aliado y tiene una gran probabilidad de afectarlo con Intemperie.","tipo":"Habilidad","elemento":"Viento"}]'::jsonb),
  ('hsr-enemy-8001010', 'honkai-star-rail', 'Engendro Ígneo', 'Flamespawn', 'esbirro', 'normal', 'Monstruos del Fragmentum', 'Elemento cristalizado con una inteligencia muy simple. Flota en el Fragmentum en forma de pájaro que emite una intensa radiación y que quema todo lo que le rodea.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_8001010.webp', '["Físico","Hielo"]'::jsonb, '[{"elemento":"Fuego","valor":40},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Físico","Hielo"],"resistencias":[{"elemento":"Fuego","valor":40},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Hielo","Rayo"],"resistencias":[{"elemento":"Fuego","valor":40},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Hielo","Viento"],"resistencias":[{"elemento":"Fuego","valor":40},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Cuántico"],"resistencias":[{"elemento":"Fuego","valor":40},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Perturbación","descripcion":"Inflige una pequeña cantidad de Daño de Fuego a un aliado.","tipo":"Habilidad","elemento":"Fuego"}]'::jsonb),
  ('hsr-enemy-4032023', 'honkai-star-rail', 'Esbirro del Rey Demonio', 'Demon King''s Minions', 'esbirro', 'normal', null, 'Fiel sirviente del Rey Demonio de la Capa Bruna. Heredó parte de su poder y su crueldad. Sus fechorías se han registrado en muchos planetas.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4032020.webp', '["Hielo","Rayo","Cuántico"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Hielo","Rayo","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Viento","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Fuego","Cuántico"],"resistencias":[{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Ofrenda conjunta: Nubarrón de la fatalidad","descripcion":"Inflige una pequeña cantidad de Daño Físico a un aliado y a los objetivos adyacentes.","tipo":"Habilidad","elemento":null},{"nombre":"Ofrenda conjunta: Final del destino","descripcion":"Inflige una pequeña cantidad de Daño Físico a todos los aliados. Una parte de los PV reducidos de los objetivos golpeados se convierte en Corrosión.","tipo":"Habilidad","elemento":null},{"nombre":"Reza por mí","descripcion":"Resiste los estados negativos de Control. Cuando Rey Demonio de la Capa Bruna vuelve a lanzar Nubarrón de la fatalidad o Final del destino, si fue invocado por este ataque y está en el estado de Ofrenda conjunta, ataca junto a Rey Demonio de la Capa Bruna. Luego esta unidad es absorbida por Rey Demonio de la Capa Bruna, con lo que este regenera los PV que fueron convertidos en Enredo agónico y obtiene Poder del desastre.","tipo":"Talento","elemento":null},{"nombre":"Brinda por mí","descripcion":"Al recibir un golpe letal mientras se encuentra en el estado de Grillete, si Rey Demonio de la Capa Bruna no tiene 0 acumulaciones de Poder del desastre, esta unidad es invocada de nuevo por él y entra en el estado de Grillete, pero a cambio Rey Demonio de la Capa Bruna pierde 1 acumulación de Poder del desastre y cierta proporción de PV. Cuando Rey Demonio de la Capa Bruna lanza Abandono sin lágrimas, absorbe a esta unidad y regenera los PV que se habían convertido en Enredo agónico.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-1012030', 'honkai-star-rail', 'Escarabajo Autómata', 'Automaton Beetle', 'esbirro', 'normal', 'Jarilo-VI', 'Autómata formado a partir de la tecnología que se conserva del viejo mundo. Sobre sus patas hay unas luces señalizadoras, por lo que tal vez se utilizaba en operaciones de minería o construcción.
El Escarabajo Autómata crea campos de fuerza durante el combate para protegerse.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_1012030.webp', '["Rayo","Viento","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, '[{"debilidades":["Rayo","Viento","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Físico","Fuego","Hielo","Rayo","Viento","Cuántico","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Rayo","Viento"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Viento"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Campo de fuerza inestable","descripcion":"Inflige Daño Físico a un aliado determinado y se proporciona a sí mismo una barrera que le permite resistir todo el daño que no sea Daño con el tiempo. Este efecto desaparece después de recibir un ataque.","tipo":"Habilidad","elemento":"Físico"}]'::jsonb),
  ('hsr-enemy-4062021', 'honkai-star-rail', 'Escuadrón de Vengadores: Perro', 'Avenger Squadron: Canine', 'esbirro', 'normal', 'Mnemoduende de Sangre Dorada', 'Un monstruo retorcido formado tras la fusión de un organismo memético del Jardín de los Recuerdos con la sangre dorada de la Destrucción. Ha comenzado a adquirir forma de perro.
Es muy agresivo, lo que demuestra que, incluso cuando la humanidad se ha evaporado, seguir a la Destrucción resulta en tal comportamiento.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4062020.webp', '["Hielo","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, null, '[{"nombre":"Mordisco de sangre viciada","descripcion":"Inflige Daño Imaginario a un aliado.","tipo":"Habilidad","elemento":"Imaginario"}]'::jsonb),
  ('hsr-enemy-3021042', 'honkai-star-rail', 'Escudo', 'The Shield', 'esbirro', 'normal', null, 'Una estatua del Escudo. La Lanza y El Escudo rodean el Alma de la Belleza y son interdependientes. El Escudo representa la determinación de defender a los vivos.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_3021040.webp', '[]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[{"nombre":"Diadema del auxilio","descripcion":"Se otorga un escudo a sí mismo. El valor de escudo aumenta mientras está en el estado de Alma libre.","tipo":"Habilidad","elemento":null},{"nombre":"Imitación del deseo veloz","descripcion":"Al recibir un golpe letal, otorga un escudo a todos los aliados. El escudo se puede acumular.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-2002020', 'honkai-star-rail', 'Espada Voladora', 'Flying Sword', 'esbirro', 'normal', null, 'Unidad de ataque que flota y está controlada por la energía vital. También se llama Espada Voladora. Está íntimamente conectada con la mente de quien la blande y es como una extensión de su voluntad.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/BossIconTemporary.webp', '["Rayo","Viento","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":40},{"elemento":"Cuántico","valor":20}]'::jsonb, '[{"debilidades":["Rayo","Viento","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":40},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Rayo","Viento","Imaginario"],"resistencias":[]}]'::jsonb, '[{"nombre":"Golpe del jade tallado","descripcion":"Inflige Daño de Hielo a un aliado.","tipo":"Habilidad","elemento":"Hielo"}]'::jsonb),
  ('hsr-enemy-2022040', 'honkai-star-rail', 'Espíritu de la Abundancia: Cánido Dorado', 'Abundance Sprite: Golden Hound', 'esbirro', 'normal', 'El Luofu de Xianzhou', 'Un perro de caza de color dorado que se mueve con elegancia y agilidad.
Cuando el Árbol de la Ambrosía se erguía orgulloso, los habitantes de Xianzhou criaban una gran variedad de criaturas fantásticas usando técnicas esotéricas. Los Cánidos Dorados eran una de las bestias de guerra que acompañaban al ejército.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_2022040.webp', '["Hielo","Rayo","Cuántico"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Hielo","Rayo","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Hielo","Rayo","Viento"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Hielo"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Cornada","descripcion":"Inflige Daño de Viento a un aliado.","tipo":"Habilidad","elemento":"Viento"},{"nombre":"Aullido","descripcion":"Al recibir un golpe letal, adelanta la acción de los enemigos adyacentes.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-2022050', 'honkai-star-rail', 'Espíritu de la Abundancia: Lupo Silvano', 'Abundance Sprite: Wooden Lupus', 'esbirro', 'normal', 'El Luofu de Xianzhou', 'Un lobo envuelto en neblina que siempre está en movimiento.
Cuando el Árbol de la Ambrosía se erguía orgulloso, los habitantes de Xianzhou criaban una gran variedad de criaturas fantásticas usando técnicas esotéricas. Los Lupos Silvanos eran una de las bestias de guerra que acompañaban al ejército.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_2022050.webp', '["Fuego","Viento","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, null, '[{"nombre":"Festín de lobos","descripcion":"Inflige Daño de Rayo a un aliado determinado y tiene una gran probabilidad de causarle Electrocución.","tipo":"Habilidad","elemento":"Rayo"},{"nombre":"Siseo agrupador","descripcion":"Invoca a una Lobohiena Sombría con su misma cantidad de PV.","tipo":"Habilidad","elemento":null}]'::jsonb),
  ('hsr-enemy-4012091', 'honkai-star-rail', 'Extremo de los Cien Ojos', 'Shoot of Hundred Eyes', 'esbirro', 'normal', null, 'Ojo monocular deambulante de la Divinidad de la Síntesis. No puede capturar imágenes y su función principal es ayudar al ojo principal a polarizar el clima.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4012091.webp', '["Físico","Hielo","Cuántico"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[]'::jsonb),
  ('hsr-enemy-4022010', 'honkai-star-rail', 'Ferroáguila Meteórica', 'Meteoric Eagle', 'esbirro', 'normal', 'Bestia crepuscular', 'En la lejana Era de la Creación, después de que Aquila creara el Dispositivo del Amanecer, Kefale le ayudó a forjar unas bestias que representaran a los Titanes. Se dice que la Ferroáguila Meteórica simboliza las plumas celestiales de Aquila que en ocasiones caen al mundo mortal.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4022010.webp', '["Viento","Cuántico","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20}]'::jsonb, '[{"debilidades":["Viento","Cuántico","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20}]},{"debilidades":["Cuántico","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20}]}]'::jsonb, '[{"nombre":"Rasgar el cielo nocturno","descripcion":"Inflige una pequeña cantidad de Daño de Viento a un aliado.","tipo":"Habilidad","elemento":"Viento"},{"nombre":"Destellos como meteoros","descripcion":"Aplica 1 acumulación de Jinete de la tormenta a un enemigo determinado. Los enemigos con Jinete de la tormenta actúan inmediatamente al finalizar su turno.","tipo":"Habilidad","elemento":null},{"nombre":"Ocultación entre sol y luna","descripcion":"Establecido inicialmente como objetivo de fila trasera.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-4032010', 'honkai-star-rail', 'Filo Corrupto de la Marea Oscura', 'Tide-Eroded Blade', 'esbirro', 'normal', 'Criatura de la marea oscura', 'Una criatura retorcida nacida de la marea oscura. El ansia de matar es la única determinación que queda en su cuerpo hueco.
Sus dos cuchillas afiladas pueden rasgar a cualquier ser vivo que se interponga en su camino. Se mueve tan rápido como un espectro y su misión es contaminar y corromper cada rincón de este mundo.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4032010.webp', '["Rayo","Cuántico","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20}]'::jsonb, '[{"debilidades":["Rayo","Cuántico","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20}]},{"debilidades":["Fuego","Rayo","Viento"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Punta de la destrucción","descripcion":"Inflige Daño Físico a un aliado y a los objetivos adyacentes.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Fin predestinado","descripcion":"Cuando un ataque inflige daño a un aliado, una parte de los PV reducidos del objetivo golpeado se convierte en Corrosión.","tipo":"Talento","elemento":null},{"nombre":"Final predeterminado","descripcion":"Cuando los PV del objetivo caen por debajo de 0, se disipa su estado de Ruptura de Debilidad y obtiene el efecto de Protección contra Debilidad.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-4012020', 'honkai-star-rail', 'Filósofo de la Furia', 'Furiae Philosopher', 'esbirro', 'normal', 'Titandeudos', 'Un titandeudo esculpido a partir del conflicto e imbuido con la sangre dorada de Nikador. En su interior contiene racionalidad robada. El propósito de su creación no es estudiar el conocimiento universal, sino investigar las brutales artes bélicas y las despiadadas leyes de la supervivencia, propagando así una locura que se pretende hacer pasar por filosofía.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4012020.webp', '["Fuego","Hielo","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, '[{"debilidades":["Fuego","Hielo","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Hielo","Viento","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Fuego"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Hielo"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]}]'::jsonb, '[{"nombre":"Guerra justa","descripcion":"Entra en el estado de Proselitismo y aumenta la VEL y el daño que inflige un enemigo.","tipo":"Habilidad","elemento":null},{"nombre":"La guerra padre","descripcion":"Inflige Daño Físico a un aliado.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Fuego eterno","descripcion":"Al recibir un golpe letal, aumenta la VEL y el daño que inflige el atacante.","tipo":"Talento","elemento":null},{"nombre":"Protector de la polis","descripcion":"Tiene cierta cantidad de acumulaciones de Armadura de guerra, que reduce el daño que recibe. Tras recibir un ataque, la cantidad de acumulaciones de Armadura de guerra disminuye en 1. Cuando las acumulaciones llegan a 0, Armadura de guerra se destruye, inflige una gran cantidad de Daño Imaginario a esta unidad y retrasa su acción. El aliado que destruye Armadura de guerra recupera energía. Cuando esta unidad es atacada después de que se haya destruido su Armadura de guerra, recibe de forma adicional una pequeña cantidad de Daño Imaginario. Armadura de guerra recupera todas sus acumulaciones cuando termina el turno de esta unidad.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-2032050', 'honkai-star-rail', 'Garra Desgarradora de Planos', 'Planeshred Claws', 'esbirro', 'normal', null, 'Garra de la bestia interior, destructora de planos celestiales, desgarradora de latitudes terrestres.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/BossIconTemporary.webp', '["Fuego","Viento"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Fuego","Viento"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Fuego","Rayo","Viento"],"resistencias":[{"elemento":"Hielo","valor":40},{"elemento":"Cuántico","valor":40},{"elemento":"Imaginario","valor":40}]}]'::jsonb, '[{"nombre":"Desgarro de planos","descripcion":"Inflige una pequeña cantidad de Daño de Viento a un aliado y a los aliados adyacentes.","tipo":"Habilidad","elemento":"Viento"},{"nombre":"División del firmamento","descripcion":"Se lanza en el estado de Resonancia. Inflige una gran cantidad de Daño de Viento a un aliado y a los objetivos adyacentes.","tipo":"Habilidad","elemento":"Viento"},{"nombre":"Salvaguardia","descripcion":"Entra en el estado de Salvaguardia y reduce el daño que recibe cuando no se ha roto su Debilidad. Al romperse su Debilidad, su acción se retrasa adicionalmente y el daño que recibe después aumenta.","tipo":"Habilidad","elemento":null}]'::jsonb),
  ('hsr-enemy-5012050', 'honkai-star-rail', 'Grafigrajo Asistente: Escribiendo a Destajo', 'Assistant Graffiti: Rusher', 'esbirro', 'normal', 'Fabulae', 'Si no fuera por la presión externa, muchos creadores de gran talento no serían capaces de escribir ni una sola palabra en toda su vida. El Grafigrajo Asistente es un fabulae que nació para resolver este problema social.
Sin embargo, a veces recurren a medidas demasiado drásticas que obligan a los creadores a defenderse, lo que a su vez se ha convertido en un nuevo problema social.
La especialidad del Grafigrajo Asistente es motivar a los creadores que están atrasados con sus entregas. ¡Rápido! ¡Haz que tu pluma se mueva! ¡No dejes que la tormenta te alcance!', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_5012050.webp', '["Hielo","Rayo"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":-20},{"elemento":"Rayo","valor":-20},{"elemento":"Viento","valor":80},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Hielo","Rayo"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":-20},{"elemento":"Rayo","valor":-20},{"elemento":"Viento","valor":80},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Hielo","Rayo"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Viento","valor":50},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Hielo","Rayo"],"resistencias":[]}]'::jsonb, '[{"nombre":"¡Vamos! ¡Date prisa!","descripcion":"Inflige Daño de Viento a un objetivo aliado determinado y tiene una gran probabilidad de afectarlo con Intemperie.","tipo":"Habilidad","elemento":"Viento"},{"nombre":"Por un oído me entra...","descripcion":"Alta RES a Viento y baja RES a sus tipos de Debilidad.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-5012040', 'honkai-star-rail', 'Grafigrajo Asistente: Manuscrito Atrasado', 'Assistant Graffiti: Slacker', 'esbirro', 'normal', 'Fabulae', 'Si no fuera por la presión externa, muchos creadores de gran talento no serían capaces de escribir ni una sola palabra en toda su vida. El Grafigrajo Asistente es un fabulae que nació para resolver este problema social.
Sin embargo, a veces recurren a medidas demasiado drásticas que obligan a los creadores a defenderse, lo que a su vez se ha convertido en un nuevo problema social.
La especialidad del Grafigrajo Asistente es resolver los problemas de retrasos en las entregas. ¿Te gusta procrastinar? ¡Entonces no escribas nada!', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_5012040.webp', '["Rayo","Viento"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":80},{"elemento":"Rayo","valor":-20},{"elemento":"Viento","valor":-20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Rayo","Viento"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":80},{"elemento":"Rayo","valor":-20},{"elemento":"Viento","valor":-20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Rayo","Viento"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":50},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Rayo","Viento"],"resistencias":[]}]'::jsonb, '[{"nombre":"¿Retrasado? ¡Pues más retraso!","descripcion":"Inflige Daño de Hielo a un aliado y tiene una gran probabilidad de aumentar el daño que recibe el objetivo atacado.","tipo":"Habilidad","elemento":"Hielo"},{"nombre":"Escribiendo con entusiasmo...","descripcion":"Alta RES a Hielo y baja RES a sus tipos de Debilidad.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-5012060', 'honkai-star-rail', 'Grafigrajo Asistente: Metiendo Prisa', 'Assistant Graffiti: Demander', 'esbirro', 'normal', 'Fabulae', 'Si no fuera por la presión externa, muchos creadores de gran talento no serían capaces de escribir ni una sola palabra en toda su vida. El Grafigrajo Asistente es un fabulae que nació para resolver este problema social.
Sin embargo, a veces recurren a medidas demasiado drásticas que obligan a los creadores a defenderse, lo que a su vez se ha convertido en un nuevo problema social.
La especialidad del Grafigrajo Asistente es presionar para que se cumplan los plazos. Así que no te escondas, no sirve de nada que desaparezcas. Contaré hasta tres...', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_5012060.webp', '["Hielo","Viento"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":-20},{"elemento":"Rayo","valor":80},{"elemento":"Viento","valor":-20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Hielo","Viento"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":-20},{"elemento":"Rayo","valor":80},{"elemento":"Viento","valor":-20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Hielo","Viento"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":50},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Hielo","Viento"],"resistencias":[]}]'::jsonb, '[{"nombre":"¡Vamos! ¡Muévete!","descripcion":"Inflige Daño de Rayo a un objetivo aliado determinado y tiene una gran probabilidad de afectarlo con Electrocución.","tipo":"Habilidad","elemento":"Rayo"},{"nombre":"Resistencia indolente","descripcion":"Alta RES a Rayo y baja RES a sus tipos de Debilidad.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-5012100', 'honkai-star-rail', 'Grupo de Chicas Mágicas', 'Magical Girl Troupe', 'esbirro', 'normal', 'Fabulae', 'Las fuerzas de seguridad de Planarcadia y su equipo de ídolos, el Grupo de Chicas Mágicas.
En la época del antiguo Benzaitengoku, las brujas eliminaban la oscuridad oculta en el mundo con danzas y canciones de exorcismo.
Con el paso del tiempo, estas brujas se convirtieron en las chicas mágicas de la Planarcadia actual, una profesión que integra el exorcismo, el control de disturbios, el antiterrorismo y el entretenimiento.
A diferencia de su adorable apariencia, las chicas mágicas a menudo deben enfrentarse a las cosas más malvadas de Planarcadia, por lo que en privado suelen tener un carácter bastante difícil.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_5012100.webp', '["Físico","Fuego","Hielo"]'::jsonb, '[{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[{"nombre":"Amo ❤ Días de tormenta","descripcion":"Inflige una pequeña cantidad de Daño de Rayo a un objetivo aliado.","tipo":"Habilidad","elemento":"Rayo"},{"nombre":"Llovizna ❤ Te extraño","descripcion":"Si se encuentra en el estado de Día lluvioso al recibir un golpe letal, inflige sucesivamente una pequeña cantidad de Daño de Rayo a aliados al azar. Tras cada golpe, tiene una gran probabilidad de afectar con Electrocución al objetivo atacado.","tipo":"Habilidad","elemento":"Rayo"},{"nombre":"Primer beso ❤ Día soleado","descripcion":"Al recibir un golpe letal mientras está en el estado de Día soleado, aumenta el Daño CRIT de todos los aliados.","tipo":"Habilidad","elemento":null},{"nombre":"Enamoramiento ❤ De la lluvia al sol","descripcion":"Al entrar en combate, se encuentra en el estado de Día lluvioso. Después de recibir Daño de Exultación o de que cualquier unidad lance una habilidad de Exultación, entra en el estado de Día soleado, retrasa su acción y genera Chiste para los aliados.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-8032040', 'honkai-star-rail', 'Guardia de Astrópolis', 'Astropolis Sentinel', 'esbirro', 'normal', 'Corporación para la Paz Interastral', 'Robots de seguridad fabricados en serie que se ven por toda Astrópolis, encargados de mantener la paz y la estabilidad.
Máquinas de la justicia frías y despiadadas que imponen la ley con calidez y golpean con contundencia.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_8032040.webp', '["Viento","Cuántico"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[{"nombre":"¿Qué cae del cielo?","descripcion":"Inflige una pequeña cantidad de Daño Físico a un aliado.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"¡Justicia y más justicia!","descripcion":"Inflige una pequeña cantidad de Daño Físico a un aliado. Solo se puede lanzar en el estado de Ejecución justiciera.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Tenaz e implacable","descripcion":"Tras lanzar ¿Qué cae del cielo?, si no está en el estado de Ejecución justiciera, entra en dicho estado. Si está en el estado de Ejecución justiciera, lanza inmediatamente ¡Justicia y más justicia! al mismo objetivo.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-4012010', 'honkai-star-rail', 'Guerrero de la Furia', 'Furiae Warrior', 'esbirro', 'normal', 'Titandeudos', 'Un titandeudo esculpido a partir del conflicto e imbuido con la sangre dorada de Nikador. Su cuerpo robusto es el escudo protector del ejército y usa su torso de piedra para atravesar el ejército rival mientras sus gruesas extremidades reparten raciones por el campo de batalla. A menudo, los soldados de Kremnos también lo usan para entrenar.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4012010.webp', '["Rayo","Cuántico","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20}]'::jsonb, null, '[{"nombre":"Colisión de la tercera órbita","descripcion":"Inflige Daño Físico a un aliado. Cuando sus acumulaciones de Armadura de guerra no son 0, tiene una probabilidad de afectar con Reverberación al objetivo. Cuando sus acumulaciones de Armadura de guerra son 0, se afecta a sí mismo con Reverberación.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Protector de la polis","descripcion":"Tiene cierta cantidad de acumulaciones de Armadura de guerra, que reduce el daño que recibe. Tras recibir un ataque, la cantidad de acumulaciones de Armadura de guerra disminuye en 1. Cuando las acumulaciones llegan a 0, Armadura de guerra se destruye, inflige una gran cantidad de Daño Imaginario a esta unidad y retrasa su acción. El aliado que destruye Armadura de guerra recupera energía. Cuando esta unidad es atacada después de que se haya destruido su Armadura de guerra, recibe de forma adicional una pequeña cantidad de Daño Imaginario. Armadura de guerra recupera todas sus acumulaciones cuando termina el turno de esta unidad.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-4032030', 'honkai-star-rail', 'Hacha Corrupta de la Marea Oscura', 'Black Tide''s Corroded Axe', 'esbirro', 'normal', 'Criatura de la marea oscura', 'Una criatura retorcida nacida de la marea oscura. El ansia de matar es la única determinación que queda en su cuerpo hueco.
Blande un hacha enorme muy pesada. Sus ataques cargados son capaces incluso de romper rocas. Quienes se interpongan en su camino acabarán siendo aplastados y corroídos.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4032030.webp', '["Físico","Rayo","Cuántico"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Físico","Rayo","Cuántico"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Hielo","Rayo","Viento"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Hachazo ígneo de la marea","descripcion":"Inflige Daño de Fuego a un aliado.","tipo":"Habilidad","elemento":"Fuego"},{"nombre":"Fuego vengador","descripcion":"Inflige a todos los aliados Daño de Fuego. El daño se reparte equitativamente entre los objetivos.","tipo":"Habilidad","elemento":"Fuego"},{"nombre":"Rencilla","descripcion":"Cuando otro enemigo es eliminado, actúa de inmediato y lanza Fuego vengador una vez. Cuando en el campo de batalla hay varias Hachas Corruptas de la Marea Oscura, solo puede activarse a la vez el talento Rencilla de una de ellas.","tipo":"Talento","elemento":null},{"nombre":"Guillotina para débiles","descripcion":"Cuando los PV del objetivo caen por debajo de 0, se disipa su estado de Ruptura de Debilidad y obtiene el efecto de Protección contra Debilidad.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-4012092', 'honkai-star-rail', 'Hueso Etmoides Marchito', 'Languid Ethmoid Bone', 'esbirro', 'normal', null, 'Estructura esquelética que sostenía uno de los ojos monoculares de la Divinidad de la Síntesis. Tras ser arrastrada por la marea oscura, heredó la capacidad de polarizar el clima.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4012092.webp', '["Físico","Cuántico","Imaginario"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20}]'::jsonb, null, '[]'::jsonb),
  ('hsr-enemy-4012093', 'honkai-star-rail', 'Hueso Lacrimal Reseco', 'Dried Lacrimal Bone', 'esbirro', 'normal', null, 'Estructura esquelética que sostenía uno de los ojos monoculares de la Divinidad de la Síntesis. Tras ser arrastrada por la marea oscura, heredó la capacidad de polarizar el clima.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4012093.webp', '["Físico","Cuántico","Imaginario"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20}]'::jsonb, null, '[]'::jsonb),
  ('hsr-enemy-2011010', 'honkai-star-rail', 'Ingenio Encantado: Dracoleón', 'Entranced Ingenium: Obedient Dracolion', 'esbirro', 'normal', 'El Luofu de Xianzhou', 'Un ingenioso invento de un trabajador de la Comisión de Artesanía. Originalmente, era una campana de alarma inanimada que se usaba para alertar, pero ahora, gracias a ciertas modificaciones, tiene una "vida" breve.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_2011010.webp', '["Viento","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, '[{"debilidades":["Viento","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Físico","Viento","Imaginario"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20}]}]'::jsonb, '[{"nombre":"Rugido de león","descripcion":"Inflige una pequeña cantidad de Daño de Fuego a un aliado y tiene cierta probabilidad de causarle Debilitación.","tipo":"Habilidad","elemento":"Fuego"}]'::jsonb),
  ('hsr-enemy-2012010', 'honkai-star-rail', 'Ingenio Encantado: Pezdragón Iluminador', 'Entranced Ingenium: Illumination Dragonfish', 'esbirro', 'normal', 'El Luofu de Xianzhou', 'Un ingenioso invento de un trabajador de la Comisión de Artesanía. Originalmente, era un iluminador inanimado que se usaba para dar luz en la oscuridad, pero ahora, gracias a ciertas modificaciones, tiene una "vida" breve.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_2012010.webp', '["Físico","Rayo","Imaginario"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, '[{"debilidades":["Físico","Rayo","Imaginario"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Hielo","Viento","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20}]}]'::jsonb, '[{"nombre":"Luminosidad nocturna","descripcion":"Inflige una pequeña cantidad de Daño de Fuego a todos los aliados y tiene una gran probabilidad de reducir la DEF de los objetivos atacados.","tipo":"Habilidad","elemento":"Fuego"},{"nombre":"Luz de vela","descripcion":"Tras recibir un golpe letal, inflige Daño de Fuego a todos los enemigos y tiene una gran probabilidad de reducir la DEF de los objetivos atacados.","tipo":"Talento","elemento":"Fuego"}]'::jsonb),
  ('hsr-enemy-2011020', 'honkai-star-rail', 'Ingenio Encantado: Sapo Nubedorada', 'Entranced Ingenium: Golden Cloud Toad', 'esbirro', 'normal', 'El Luofu de Xianzhou', 'Un ingenioso invento de un trabajador de la Comisión de Artesanía. Originalmente, era un incensario inanimado que se usaba para purificar el aire, pero ahora, gracias a ciertas modificaciones, tiene una "vida" breve.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_2011020.webp', '["Rayo","Cuántico"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Rayo","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Rayo","Viento","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Rayo","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]}]'::jsonb, '[{"nombre":"Niebla espesa","descripcion":"Inflige una pequeña cantidad de Daño Imaginario a un aliado y tiene cierta probabilidad de reducir la VEL de ese aliado.","tipo":"Habilidad","elemento":"Imaginario"}]'::jsonb),
  ('hsr-enemy-8022030', 'honkai-star-rail', 'Insecto Aguijoneador Corrosivo', 'Gnaw Sting', 'esbirro', 'normal', 'El Enjambre', 'Una variedad de insecto aguijoneador que mutó durante la reproducción. Se especializa en usar las toxinas cuánticas que tiene en las mandíbulas para corroer el cuerpo de sus presas.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_8022030.webp', '["Físico","Hielo"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":40},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Físico","Hielo"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":40},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Hielo","Imaginario"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]}]'::jsonb, '[{"nombre":"Choque de cuernos","descripcion":"Inflige Daño Cuántico a un aliado (da prioridad a los objetivos afectados por Enredo) y aplica una acumulación adicional de Enredo.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"Elegía a la corrosión","descripcion":"Tras recibir un golpe letal, inflige Daño Cuántico a todos los enemigos y aumenta el daño que reciben.","tipo":"Talento","elemento":"Cuántico"},{"nombre":"Sustento","descripcion":"Al recibir un golpe letal, todos los aliados regeneran una pequeña cantidad de PV.","tipo":"Talento","elemento":null},{"nombre":"Perturbación","descripcion":"Cada acumulación de Hormona de crecimiento aumenta el ATQ en cierta cantidad. Se puede acumular hasta 3 veces. Cuando se alcanzan 3 acumulaciones, si el aliado que recibe el ataque de Choque de cuernos no está en el estado de Enredo, hay una gran probabilidad de afectarlo con ese estado.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-8022010', 'honkai-star-rail', 'Insecto Aguijoneador Inmaduro', 'Juvenile Sting', 'esbirro', 'normal', 'El Enjambre', 'Cría del Gran Insecto Aguijoneador. Las crías del Gran Insecto Aguijoneador se clasifican según su crecimiento en Insecto Aguijoneador Inmaduro e Insecto Aguijoneador Menor.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_8022010.webp', '["Cuántico","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20}]'::jsonb, '[{"debilidades":["Cuántico","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20}]},{"debilidades":["Físico","Cuántico"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Alas extendidas","descripcion":"Inflige una pequeña cantidad de Daño de Viento a un aliado y tiene una gran probabilidad de afectarlo con Intemperie.","tipo":"Habilidad","elemento":"Viento"},{"nombre":"División meiótica","descripcion":"Produce 1 copia de sí mismo. Este efecto puede volver a activarse tras 2 turnos.","tipo":"Habilidad","elemento":null},{"nombre":"Elegía entomológica","descripcion":"Tras recibir un golpe letal, inflige Daño de Viento a todos los enemigos y tiene una gran probabilidad de aumentar ligeramente el daño que reciben.","tipo":"Talento","elemento":"Viento"}]'::jsonb),
  ('hsr-enemy-8022020', 'honkai-star-rail', 'Insecto Aguijoneador Menor', 'Lesser Sting', 'esbirro', 'normal', 'El Enjambre', 'Cría del Gran Insecto Aguijoneador. Las crías del Gran Insecto Aguijoneador se clasifican según su crecimiento en Insecto Aguijoneador Inmaduro e Insecto Aguijoneador Menor.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_8022020.webp', '["Físico","Fuego","Imaginario"]'::jsonb, '[{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, '[{"debilidades":["Físico","Fuego","Imaginario"],"resistencias":[{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Físico","Fuego","Cuántico"],"resistencias":[{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Preparación para el combate","descripcion":"Entra en el estado de Recarga. Lanza Detonación explosiva en la siguiente acción.","tipo":"Habilidad","elemento":null},{"nombre":"Detonación explosiva","descripcion":"Explota e inflige Daño de Viento a un aliado determinado y a los aliados adyacentes y tiene una gran probabilidad de causar Cólera a los objetivos.","tipo":"Habilidad","elemento":"Viento"},{"nombre":"Elegía entomológica","descripcion":"Tras recibir un golpe letal, inflige Daño de Viento a todos los enemigos y tiene una gran probabilidad de aumentar ligeramente el daño que reciben.","tipo":"Talento","elemento":"Viento"},{"nombre":"Nutrición","descripcion":"Al recibir un golpe letal, los aliados recuperan pts. de habilidad básica.","tipo":"Talento","elemento":null},{"nombre":"Proliferación","descripcion":"Cada acumulación de Hormona de crecimiento aumenta el ATQ en cierta cantidad y se puede acumular hasta 3 veces. Cuando se alcanzan 3 acumulaciones, actúa inmediatamente.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-3021020', 'honkai-star-rail', 'La Distinguida', '"The Honored"', 'esbirro', 'normal', null, 'Una estatua de La Distinguida. Cuenta la leyenda que hubo una vez una rosa que la Belleza besó, lo que la imbuyó de un atractivo eterno.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_3021020.webp', '["Físico","Hielo"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Físico","Hielo"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Fuego"],"resistencias":[{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Fuego","Hielo","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Distinción de la Reina Roja","descripcion":"Aplica 1 acumulación de aumento de daño al enemigo Argenti. Aumenta las acumulaciones de aumento de daño mientras se encuentra en el estado Alma libre.","tipo":"Habilidad","elemento":null},{"nombre":"Piedra de los cimientos desplomados","descripcion":"Al recibir un golpe letal, aplica 1 acumulación de aumento de daño al atacante. Aumenta las acumulaciones de aumento de daño mientras se encuentra en el estado Alma libre.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-1002013', 'honkai-star-rail', 'Lanza del Frío Infinito', 'Lance of the Eternal Freeze', 'esbirro', 'normal', null, 'Enorme lanza de hielo invocada por Cocolia. La rodea un frío penetrante que perfora la carne como una espada.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_1002013.webp', '["Fuego","Rayo"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Fuego","Rayo"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Viento","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Rayo"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Viento"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Eco del Siempreinvierno","descripcion":"Inflige una pequeña cantidad de Daño de Hielo a todos los aliados.","tipo":"Habilidad","elemento":"Hielo"},{"nombre":"Persecución bajo cero","descripcion":"Fija un objetivo. Algunas habilidades de Cocolia, Madre de Falsedades (ilusión) se lanzarán una vez más sobre el objetivo fijado hasta que la Debilidad de Lanza del Frío Infinito (ilusión) se rompa o sea derrotada.","tipo":"Habilidad","elemento":"Hielo"}]'::jsonb),
  ('hsr-enemy-5012030', 'honkai-star-rail', 'Lectura Agresiva', 'Aggressive Reading Material', 'esbirro', 'normal', 'Fabulae', 'Como dice el refrán: comprar libros es como una avalancha, pero leerlos es como hilar seda. Los amantes de los libros siempre compran libros nuevos, pero rara vez los abren para leerlos.
La culpa de tener tantos libros sin leer y el autoengaño de pensar que algún día los leerán se entrelazan para dar origen a un fabulae feroz: Lectura Agresiva.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_5012030.webp', '["Físico","Fuego","Rayo"]'::jsonb, '[{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[{"nombre":"¡Lee o muere!","descripcion":"Inflige una pequeña cantidad de Daño Físico a un aliado.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Maldición del conocimiento","descripcion":"Al comienzo del combate, cuando está en el estado Inmersión lectora, el daño infligido aumenta y el daño recibido se reduce. El estado de Inmersión lectora se disipa tras recibir Daño de Exultación o cuando los aliados obtienen Chiste y alcanza cierta cantidad.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-2022051', 'honkai-star-rail', 'Lobohiena Sombría', 'Shadow Jackhyena', 'esbirro', 'normal', null, 'Ilusión creada por un Lupo Silvano.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/BossIconTemporary.webp', '["Fuego","Viento","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, '[{"debilidades":["Fuego","Viento","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Fuego","Viento","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Festín de lobos","descripcion":"Inflige Daño de Rayo a un aliado determinado y tiene una gran probabilidad de causarle Electrocución.","tipo":"Habilidad","elemento":"Rayo"}]'::jsonb),
  ('hsr-enemy-4032070', 'honkai-star-rail', 'Logos Manipulado', 'Manipulated Logos', 'esbirro', 'normal', null, 'La forma del mundo, el deseo de búsqueda, y el espacio infinito que les da forma. De ellos nace todo el intelecto de la inteligencia. Ya no es un títere, morirá en el funeral de la sabiduría, dejando una lápida forjada en hierro.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4032070.webp', '[]'::jsonb, '[]'::jsonb, null, '[{"nombre":"Por el caos","descripcion":"Inflige Daño Cuántico a un aliado y a los objetivos adyacentes.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"Búsqueda insensata","descripcion":"Fija como objetivo a 1 aliado y entra en el estado Comienzo de la rebelión. Anticreador lanza \"No hay lealtad para los tiranos\" en su siguiente acción.","tipo":"Habilidad","elemento":null},{"nombre":"Erradicación de falsedades","descripcion":"Inflige Daño Cuántico a un aliado y a los objetivos adyacentes.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"Inmortal e indestructible","descripcion":"Inmune a los efectos que alteran el orden de acción, exceptuando los de Anticreador. Logos no se puede eliminar. Tras recibir un golpe letal, es afectado con el estado Herida grave, recupera la energía de todos los aliados y disipa el estado de Bloqueo de acción.","tipo":"Talento","elemento":null},{"nombre":"Destruir para construir","descripcion":"Inflige Daño Cuántico a todos los aliados y hace que pierdan 1 pt. de habilidad básica.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"La rebelión de un necio","descripcion":"Entra en el estado Comienzo de la rebelión. Anticreador lanza \"La corona de divinidad se destrozará\" en su siguiente acción.","tipo":"Habilidad","elemento":null},{"nombre":"Recurrencia eterna","descripcion":"Cuando esta unidad es afectada con el estado Herida grave, en la siguiente acción regenera todos los PV y disipa el estado Herida grave.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-8012200', 'honkai-star-rail', 'Loto de la Abundancia', 'Abundance Lotus', 'esbirro', 'normal', null, 'Una flor espectral que florece sin raíces y nace de la nada. Phantylia empleó el Árbol de la Ambrosía como recipiente para formar un cuerpo y tocar el poder de la Abundancia.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_8012200.webp', '["Viento","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, '[{"debilidades":["Viento","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Fuego","Rayo","Viento","Imaginario"],"resistencias":[{"elemento":"Físico","valor":40},{"elemento":"Hielo","valor":40},{"elemento":"Cuántico","valor":40}]}]'::jsonb, '[{"nombre":"Samsara","descripcion":"Reduce en 1 los pts. de habilidad básica de los aliados.","tipo":"Habilidad","elemento":null},{"nombre":"Terapia","descripcion":"Regenera sus propios PV al principio de cada turno.","tipo":"Talento","elemento":null},{"nombre":"Moksha","descripcion":"Tras recibir un golpe letal, los aliados recuperan 3 pts. de habilidad básica.","tipo":"Talento","elemento":null},{"nombre":"Antivida","descripcion":"Reduce la energía de un aliado.","tipo":"Habilidad","elemento":null},{"nombre":"Antidestrucción","descripcion":"Tras recibir un golpe letal, todo el equipo recupera energía. Al mismo tiempo, inflige una cantidad fija de daño a Provocador Oportunista y aumenta el nivel de Bonificación de la Abundancia de los aliados. Bonificación de la Abundancia aumenta el daño que infligen los personajes.","tipo":"Talento","elemento":null},{"nombre":"Condena eterna","descripcion":"Inflige Daño Imaginario a un objetivo fijado. Cuantos más objetivos haya fijado, más daño inflige.","tipo":"Habilidad","elemento":"Imaginario"}]'::jsonb),
  ('hsr-enemy-8012210', 'honkai-star-rail', 'Loto de la Destrucción', 'Destruction Lotus', 'esbirro', 'normal', null, 'Una flor espectral que florece sin raíces y nace de la nada. Phantylia empleó el Árbol de la Ambrosía como recipiente para formar un cuerpo, pero no renunció a la autoridad de la Destrucción.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_8012210.webp', '["Rayo","Cuántico","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20}]'::jsonb, '[{"debilidades":["Rayo","Cuántico","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20}]},{"debilidades":["Fuego","Rayo","Viento","Imaginario"],"resistencias":[{"elemento":"Físico","valor":40},{"elemento":"Hielo","valor":40},{"elemento":"Cuántico","valor":40}]}]'::jsonb, '[{"nombre":"Extracción del prana negro","descripcion":"Gran probabilidad de que un aliado se vea afectado por Extractor de prana.","tipo":"Habilidad","elemento":null},{"nombre":"Hecatombe","descripcion":"Inflige Daño de Rayo a un aliado según su porcentaje de PV máx. Este daño ignora la DEF del objetivo.","tipo":"Habilidad","elemento":"Rayo"},{"nombre":"Florecimiento","descripcion":"En el estado de Florecimiento, usa Hecatombe en la siguiente acción. Cuando Loto de la Destrucción está en estado de Florecimiento y le afecta Ruptura de Debilidad, es derrotado o se disipa el estado de Florecimiento, el daño que recibe Phantylia la Inmortal aumenta y se retrasa su acción.","tipo":"Talento","elemento":null},{"nombre":"Hibernación","descripcion":"Después de recibir un golpe letal entra en estado de Hibernación.","tipo":"Talento","elemento":null},{"nombre":"Regreso del prana negro","descripcion":"Tras recibir un golpe letal, disipa los estados negativos de todo el equipo y regenera sus PV. Al mismo tiempo, inflige una cantidad fija de daño a Provocador Oportunista y aumenta el nivel de Bonificación de la Destrucción de los aliados. Bonificación de la Destrucción aumenta el efecto de Ruptura de los personajes.","tipo":"Talento","elemento":null},{"nombre":"Salvaguardia","descripcion":"Entra en el estado de Salvaguardia y reduce el daño que recibe cuando no se ha roto su Debilidad. Al romperse su Debilidad, su acción se retrasa adicionalmente y el daño que recibe después aumenta.","tipo":"Talento","elemento":null},{"nombre":"Condena eterna","descripcion":"Inflige Daño Imaginario a un objetivo fijado. Cuantos más objetivos haya fijado, más daño inflige.","tipo":"Habilidad","elemento":"Imaginario"}]'::jsonb),
  ('hsr-enemy-5022010', 'honkai-star-rail', 'Loto Maldeseo', 'Illwish Lotus', 'esbirro', 'normal', null, 'Ramas que se extienden a partir de la proliferación infinita de la carne y sangre de Shuhu, una flor del mal nutrida por todo tipo de sueños e ilusiones retorcidos.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_5022010.webp', '["Fuego","Hielo","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, null, '[{"nombre":"Primera floración","descripcion":"Otorga una acumulación de Sonrisa malévola a Júbilo Inverso: Archiloto Maldeseo.","tipo":"Habilidad","elemento":null},{"nombre":"Burla letal","descripcion":"Tras recibir un golpe letal, genera Chiste para los aliados.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-3002021', 'honkai-star-rail', 'Maestro Plátano de Fortuna de la Oficina Platanoacadémica', 'Banacademic Office''s Fortune BananAdvisor', 'esbirro', 'normal', 'Compañía Teatral de Terrores', 'Originalmente, un Vendefortunas equipado con material académico de la escuela de Fortuna, pero el virus memético lo infectó y este se convirtió en material bananacadémico. Una mente tan despierta como un plátano es la mejor arma del mercado, y las platanotransacciones de resultados impredecibles están llenando de banansiedad a los monos.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_3002021.webp', '["Fuego","Rayo","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, '[{"debilidades":["Fuego","Rayo","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Fuego","Rayo","Imaginario"],"resistencias":[{"elemento":"Físico","valor":40},{"elemento":"Hielo","valor":40},{"elemento":"Viento","valor":40},{"elemento":"Cuántico","valor":40}]}]'::jsonb, '[{"nombre":"Los monos buenos sacan buenas notas","descripcion":"Recupera pts. de habilidad básica para los aliados. Esta habilidad solo se puede usar en el estado Canal del descanso.","tipo":"Habilidad","elemento":null},{"nombre":"A los monos malos les quitan nota","descripcion":"Reduce los pts. de habilidad básica de los aliados. Esta habilidad solo se puede usar en el estado Canal de la clase.","tipo":"Habilidad","elemento":null},{"nombre":"Cambio del bananatemario","descripcion":"Cambia el estado Canal del descanso al estado Canal de la clase.","tipo":"Habilidad","elemento":null},{"nombre":"Desorden del bananatemario","descripcion":"Tras recibir un ataque, cambia el estado Canal de la clase al estado Canal del descanso. Cuando se encuentra en el estado Canal del descanso, no cambia tras recibir un ataque.","tipo":"Talento","elemento":null},{"nombre":"Los monos buenos tienen buenas calificaciones","descripcion":"Al cambiar del estado Canal de la clase al estado Canal del descanso, los aliados recuperan pts. de habilidad básica.","tipo":"Talento","elemento":null},{"nombre":"Incidente bananacadémico","descripcion":"Tras recibir cierta cantidad de ataques, cambia el estado Canal de la clase al estado Canal del descanso y es afectado con Ruptura de Debilidad.","tipo":"Talento","elemento":null},{"nombre":"Pasaje de lista","descripcion":"Inflige Daño Físico a un aliado.","tipo":"Habilidad","elemento":"Físico"}]'::jsonb),
