  ('hsr-enemy-3001020', 'honkai-star-rail', 'Máscara Bailarina de la Compañía Teatral de Terrores', 'Dreamjolt Troupe''s Birdskull', 'esbirro', 'normal', 'Compañía Teatral de Terrores', 'Máquina de servicio de Colonipenal que perdió el control debido a las interferencias emocionales en el paisaje onírico.
Antes era una pieza de atrezo en el teatro, y continúa interpretando la farsa en el escenario tras perder el control, dando desordenados pasos de baile en todas las direcciones.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_3001020.webp', '["Rayo","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, '[{"debilidades":["Rayo","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Hielo","Rayo"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Invitación a bailar","descripcion":"Inflige una pequeña cantidad de Daño Físico a un aliado y tiene cierta probabilidad de causarle Sangrado.","tipo":"Habilidad","elemento":"Físico"}]'::jsonb),
  ('hsr-enemy-8001030', 'honkai-star-rail', 'Máscara Impensativa', 'Mask of No Thought', 'esbirro', 'normal', 'Monstruos del Fragmentum', 'Las víctimas de la corrosión del Fragmentum se entretejen para formar extrañas criaturas. Sus rostros retorcidos están desprovistos de todo pensamiento y emoción, y cualquier rastro de humanidad que tuvieran anteriormente ha desaparecido.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_8001030.webp', '["Fuego","Cuántico"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Fuego","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Rayo","Viento"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Rayo","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Hielo","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Rayo iridiscente","descripcion":"Inflige una pequeña cantidad de Daño Imaginario a un aliado.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"Rayo concentrado","descripcion":"Aumenta el ATQ de todos los enemigos.","tipo":"Habilidad","elemento":null},{"nombre":"Explosión de energía","descripcion":"Tras recibir un golpe letal, todos los aliados recuperan energía.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-5012092', 'honkai-star-rail', 'Mecatrón de Circe', 'Circe''s Mechatron', 'esbirro', 'normal', 'Fabulae', 'Mecatrón de uso general de Planarcadia. NLS viene de "No Lo Sé".', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_5012090.webp', '["Físico","Fuego","Rayo"]'::jsonb, '[{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[{"nombre":"Potenciando fuerza","descripcion":"Entra en el estado de ¡Potenciación de fuerza! y lanza Molinillo rompecaras en el siguiente turno.","tipo":"Habilidad","elemento":null},{"nombre":"Molinillo rompecaras","descripcion":"Inflige Daño Físico a un objetivo.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Fallo de identificación amigo-enemigo","descripcion":"Cambia su objetivo de ataque entre aliados y enemigos tras cada ataque de un aliado.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-5012090', 'honkai-star-rail', 'Mecatrón de Uso Civil NLS', 'SD Civilian Mechatron', 'esbirro', 'normal', 'Fabulae', 'Mecatrón de uso general de Planarcadia. NLS viene de "No Lo Sé".', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_5012090.webp', '["Físico","Fuego","Rayo"]'::jsonb, '[{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[{"nombre":"Potenciando fuerza","descripcion":"Entra en el estado de ¡Potenciación de fuerza! y lanza Molinillo rompecaras en el siguiente turno.","tipo":"Habilidad","elemento":null},{"nombre":"Molinillo rompecaras","descripcion":"Inflige Daño Físico a un aliado y genera Chiste para los aliados. Tiene una probabilidad de afectar con Reverberación potente al aliado atacado.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Fallo de identificación amigo-enemigo","descripcion":"Cuando está en el estado de ¡Potenciación de fuerza!, actúa inmediatamente tras recibir un ataque. Hay una pequeña probabilidad de infligir Daño Físico a un enemigo adyacente al azar y de que los aliados obtengan Chiste; de lo contrario, lanza Molinillo rompecaras a un aliado al azar. Si el daño recibido con dicho ataque es Daño de Exultación, ataca siempre a un enemigo. Este efecto solo se puede activar 1 vez mientras dure ¡Potenciación de fuerza!.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-3012010', 'honkai-star-rail', 'Meme de la Zona de los Recuerdos: Algo en el Espejo', 'Memory Zone Meme "Something In The Mirror"', 'esbirro', 'normal', 'Memes de la Zona de los Recuerdos', 'Una entidad imbuida de una cognición específica acumulada a partir de los fragmentos del subconsciente de la Zona de los Recuerdos.
Los seres vivos utilizan espejos para comprender el mundo y construir la percepción de sí mismos. Esta entidad memética sin forma se refleja en el espejo y produce ilusiones cambiantes.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_3012010.webp', '["Físico","Viento","Imaginario"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, null, '[{"nombre":"Reconocimiento en el espejo","descripcion":"Se transforma en otro enemigo y copia sus habilidades. Tras transformarse, hereda sus propios atributos base.","tipo":"Habilidad","elemento":null}]'::jsonb),
  ('hsr-enemy-3011010', 'honkai-star-rail', 'Meme de la Zona de los Recuerdos: Omnividente', 'Memory Zone Meme "Allseer"', 'esbirro', 'normal', 'Memes de la Zona de los Recuerdos', 'Una entidad imbuida de una cognición específica acumulada a partir de los fragmentos del subconsciente de la Zona de los Recuerdos.
Observación, retrospección, inspección... En la búsqueda de la supervivencia y la comprensión existencial, los recuerdos de "mirar" y "ver" van de la mano y terminan convirtiéndose en una parte integral de la vida.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_3011010.webp', '["Hielo","Rayo"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Hielo","Rayo"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Rayo"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Mirada del otro","descripcion":"Inflige una pequeña cantidad de Daño Cuántico a un aliado y retrasa la acción de ese aliado.","tipo":"Habilidad","elemento":"Cuántico"}]'::jsonb),
  ('hsr-enemy-3012020', 'honkai-star-rail', 'Meme de la Zona de los Recuerdos: Rompecorazones', 'Memory Zone Meme "Heartbreaker"', 'esbirro', 'normal', 'Memes de la Zona de los Recuerdos', 'Una entidad imbuida de una cognición específica acumulada a partir de los fragmentos del subconsciente de la Zona de los Recuerdos.
La vida se encuentra dividida por barreras impenetrables, obstruyendo la intrusión de lo ajeno. Sin embargo, bajo esa coraza inquebrantable, hay una región frágil y sin nombre.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_3012020.webp', '["Fuego","Hielo","Rayo"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[{"nombre":"Desviación estructural","descripcion":"Inflige Daño Físico a un aliado.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Escudo de lo inquebrantable","descripcion":"Entra en el estado de Salvaguardia y reduce el daño que recibe cuando no se ha roto su Debilidad. Al romperse su Debilidad, su acción se retrasa adicionalmente y el daño que recibe después aumenta.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-3012040', 'honkai-star-rail', 'Meme de la Zona de los Recuerdos: Vanidad insaciable', 'Memory Zone Meme "Insatiable Vanity"', 'esbirro', 'normal', 'Memes de la Zona de los Recuerdos', 'Una entidad imbuida de una cognición específica acumulada a partir de los fragmentos del subconsciente de la Zona de los Recuerdos.
La ostentación de los transeúntes, el aferrarse de los débiles, la adulación de los serviles... La vanidad incesante se convirtió en una entidad memética que busca un huésped ansioso de fama y fortuna.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_3012040.webp', '["Físico","Fuego"]'::jsonb, '[{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[{"nombre":"Coronado en Nombre Mortal","descripcion":"Posee a un enemigo y lo afecta con el estado de Corona de la vanidad. Disipa los efectos de Control que tenga y recupera su Firmeza.","tipo":"Habilidad","elemento":null},{"nombre":"La Caída Auténtica","descripcion":"Los enemigos en el estado de Corona de la vanidad regeneran PV tras recibir un ataque, pero también obtienen Debilidad Física y Debilidad de Fuego y reciben más Daño de Ruptura. Cuando se rompe la Debilidad o se derrota al enemigo afectado, se disipa el estado de Corona de la vanidad y Vanidad insaciable es derrotado.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-4062010', 'honkai-star-rail', 'Mnemoduende de Sangre Dorada: Faisán', 'Ichor Memosprite: Pheasant', 'esbirro', 'normal', 'Mnemoduende de Sangre Dorada', 'Un monstruo retorcido formado tras la fusión de un organismo memético del Jardín de los Recuerdos con la sangre dorada de la Destrucción. Ha comenzado a adquirir forma de faisán.
Es muy ruidoso y siempre actúa en grupo, lo que demuestra que, incluso cuando la humanidad se ha evaporado, seguir a la Destrucción resulta en tal comportamiento.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4062010.webp', '["Físico","Fuego"]'::jsonb, '[{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[{"nombre":"Picoteo de sangre viciada","descripcion":"Inflige una pequeña cantidad de Daño Imaginario a un aliado.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"Resonancia de sangre viciada","descripcion":"Esta unidad y cualquier otro Mnemoduende de Sangre Dorada: Faisán que haya en el campo de batalla entran en el estado Resonancia de sangre viciada.","tipo":"Habilidad","elemento":null}]'::jsonb),
  ('hsr-enemy-4062020', 'honkai-star-rail', 'Mnemoduende de Sangre Dorada: Perro', 'Ichor Memosprite: Canine', 'esbirro', 'normal', 'Mnemoduende de Sangre Dorada', 'Un monstruo retorcido formado tras la fusión de un organismo memético del Jardín de los Recuerdos con la sangre dorada de la Destrucción. Ha comenzado a adquirir forma de perro.
Es muy agresivo, lo que demuestra que, incluso cuando la humanidad se ha evaporado, seguir a la Destrucción resulta en tal comportamiento.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4062020.webp', '["Hielo","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, null, '[{"nombre":"Mordisco de sangre viciada","descripcion":"Inflige Daño Imaginario a un aliado.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"Mancha de sangre viciada","descripcion":"Al comenzar la batalla, obtiene el estado Mancha de sangre viciada.","tipo":"Talento","elemento":null},{"nombre":"Sangre viciada compartida","descripcion":"Al recibir un golpe letal, aplica el estado Mancha de sangre viciada a los enemigos adyacentes.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-2032021', 'honkai-star-rail', 'Mok Tok', 'Mok Tok', 'esbirro', 'normal', 'El Luofu de Xianzhou', 'Un soldado lobo borisin que bebió la sangre de Hoolay y que se convirtió voluntariamente en una pieza desechada.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_2032020.webp', '["Físico","Viento"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[{"nombre":"Mordisco","descripcion":"Inflige Daño Físico a un aliado. Si está afectado por Locura lunar, regenera PV después de atacar al objetivo aliado.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Deglución lupina","descripcion":"Después de que un enemigo ataque, aplica 1 acumulación de Sed de sangre a los enemigos que puedan entrar en el estado de Locura lunar. Cuando Sed de sangre alcanza cierta cantidad de acumulaciones, el enemigo entra en el estado de Locura lunar.\nEn el orden de acción aparece una cuenta regresiva de Locura lunar. Cuando comienza el turno de la cuenta regresiva, se disipa el estado de Locura lunar de todos los enemigos.","tipo":"Habilidad","elemento":"Físico"}]'::jsonb),
  ('hsr-enemy-4032060', 'honkai-star-rail', 'Mythos Aprisionado', 'Imprisoned Mythos', 'esbirro', 'normal', null, 'Las epopeyas, el romance de las leyendas y las largas eras que les da valor. De ellos nace toda la espiritualidad de la fe. Ya no es un prisionero, morirá en el funeral de la sabiduría, dejando una lápida forjada en hierro.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4032060.webp', '[]'::jsonb, '[]'::jsonb, null, '[{"nombre":"Inducción a la locura","descripcion":"Inflige Daño Imaginario a un aliado y retrasa su acción.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"Maldición profana","descripcion":"Fija como objetivo a 1 aliado y entra en el estado Llegada del alivio. Anticreador lanza \"La caverna no será el fin\" en su siguiente acción.","tipo":"Habilidad","elemento":null},{"nombre":"Ecos de la tragedia","descripcion":"Inflige Daño Imaginario a un aliado y retrasa su acción.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"Incendio del sufrimiento eterno","descripcion":"Fija como objetivo a 2 aliados y entra en el estado Llegada del alivio. Anticreador lanza \"La prisión del espíritu arderá\" en su siguiente acción.","tipo":"Habilidad","elemento":null},{"nombre":"Recurrencia eterna","descripcion":"Cuando esta unidad es afectada con el estado Herida grave, en la siguiente acción regenera todos los PV y disipa el estado Herida grave.","tipo":"Talento","elemento":null},{"nombre":"Inmortal e indestructible","descripcion":"Inmune a los efectos que alteran el orden de acción, exceptuando los de Anticreador. Mythos no se puede eliminar. Tras recibir un golpe letal, es afectado con el estado Herida grave, adelanta la acción de todos los aliados y disipa el estado de Bloqueo de acción.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-2002030', 'honkai-star-rail', 'Oficial Espectral', 'Wraith Warden', 'esbirro', 'normal', 'El Luofu de Xianzhou', 'Soldado que acompaña a los jueces de la Comisión de los Diez Líderes a desempeñar sus tareas.
Lleva una máscara blanca y negra que simboliza a un mensajero procedente del inframundo. Porta una antigua guillotina y sus ataques son tan duros e implacables como el trabajo de la Comisión de los Diez Líderes.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_2002030.webp', '["Físico","Hielo","Viento"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Físico","Hielo","Viento"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Hielo","Viento","Imaginario"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Físico","Hielo","Imaginario"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Físico","Viento","Imaginario"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20}]}]'::jsonb, '[{"nombre":"Sierra del mal","descripcion":"Inflige una pequeña cantidad de Daño Físico a un aliado y tiene una probabilidad de afectarlo con Reverberación. Cuando los objetivos afectados por Reverberación reciben un ataque, entran en el estado de Reverberación potente y se disipa el estado de Reverberación. El objetivo afectado por Reverberación potente no puede realizar acciones.","tipo":"Habilidad","elemento":"Físico"}]'::jsonb),
  ('hsr-enemy-2022110', 'honkai-star-rail', 'Oficial Poseída por Mara', 'Mara-Struck Warden', 'esbirro', 'normal', 'El Luofu de Xianzhou', 'Soldado de la Comisión de los Diez Líderes que ha sido poseída por Mara.
Mientras sean mortales de carne y hueso, los nativos de Xianzhou nunca podrán escapar de su destino.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_2022110.webp', '["Hielo","Rayo","Cuántico"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Hielo","Rayo","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Hielo","Rayo"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Rayo","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Hielo","Rayo","Viento"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Fuego","Hielo","Rayo","Viento","Cuántico","Imaginario"],"resistencias":[]},{"debilidades":["Físico","Fuego","Hielo","Rayo"],"resistencias":[{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Viento","Cuántico","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20}]}]'::jsonb, '[{"nombre":"Sierra del mal: corte","descripcion":"Inflige una pequeña cantidad de Daño de Viento a un aliado.","tipo":"Habilidad","elemento":"Viento"},{"nombre":"Sierra del mal: separación","descripcion":"Inflige Daño de Viento a un aliado.","tipo":"Habilidad","elemento":"Viento"},{"nombre":"Locura","descripcion":"Al comenzar la batalla, entra en el estado de Locura. Mientras está en este estado, usa Sierra del mal: separación.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-5012111', 'honkai-star-rail', 'Osipachi Bandido', 'Master Thief Furbo', 'esbirro', 'normal', 'Fabulae', 'Un reportero osipachi del Semanario Pachi. Se inventa las noticias de chismes y es un villano a quien le encanta transformarse. De vez en cuando se escabulle del trabajo y se esconde en un rincón, creyendo que así no lo verá nadie.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_5012110.webp', '["Rayo","Cuántico","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20}]'::jsonb, null, '[{"nombre":"Captura","descripcion":"Inflige una pequeña cantidad de Daño Imaginario a un aliado.","tipo":"Habilidad","elemento":"Imaginario"}]'::jsonb),
  ('hsr-enemy-2002010', 'honkai-star-rail', 'Patrullero de los Nimbocaballeros', 'Cloud Knights Patroller', 'esbirro', 'normal', 'El Luofu de Xianzhou', 'Miembro de los Nimbocaballeros del Luofu de Xianzhou que patrulla y protege en tierra. Lleva una armadura de plata y porta un Archa del Devastador. Se encarga de mantener el orden en todos los dominios.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_2002010.webp', '["Fuego","Viento","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, '[{"debilidades":["Fuego","Viento","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Fuego","Rayo","Viento"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20}]}]'::jsonb, '[{"nombre":"Filo de nube","descripcion":"Inflige una pequeña cantidad de Daño de Viento a un aliado y tiene una gran probabilidad de aumentar ligeramente el daño que recibe el objetivo.","tipo":"Habilidad","elemento":"Viento"}]'::jsonb),
  ('hsr-enemy-8032010', 'honkai-star-rail', 'Personal Subalterno: Trabajador', 'Grunt: Field Personnel', 'esbirro', 'normal', 'Corporación para la Paz Interastral', 'Empleado subalterno de la Corporación para la Paz Interastral. Se encarga de solucionar las "chapuzas empresariales" y evitar que asciendan a niveles superiores. Su salario es una miseria, y el único alojamiento que puede permitirse es una habitación compartida a bordo de una de las naves de la Corporación.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_8032010.webp', '["Fuego","Hielo"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Fuego","Hielo"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Cuántico","Imaginario"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20}]},{"debilidades":["Rayo","Viento"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Hielo","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Físico","Rayo","Viento"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Hora de fichar","descripcion":"Inflige una pequeña cantidad de Daño Físico a un aliado.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Resultados mejorados","descripcion":"Después de