  ('hsr-enemy-8032020', 'honkai-star-rail', 'Personal Subalterno: Vigilante de Seguridad', 'Grunt: Security Personnel', 'esbirro', 'normal', 'Corporación para la Paz Interastral', 'Empleado subalterno de la Corporación para la Paz Interastral. Se encarga principalmente de mantener el orden en los dominios de la corporación. Su salario es una miseria, y el único alojamiento que puede permitirse es una habitación compartida a bordo de una de las naves de la Corporación.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_8032020.webp', '["Físico","Fuego","Hielo"]'::jsonb, '[{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Físico","Fuego","Hielo"],"resistencias":[{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Viento","Cuántico","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20}]},{"debilidades":["Físico","Rayo","Viento"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Rayo","Viento"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Hielo","Rayo"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Rayo","Viento","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Demanda judicial","descripcion":"Inflige una pequeña cantidad de Daño Físico a un aliado 