  ('hsr-enemy-1002011', 'honkai-star-rail', 'Pica Glacial', 'Ice Edge', 'esbirro', 'normal', null, 'Lanza de hielo gigante creada por la Guardiana. Libera un viento gélido que barre el campo de batalla.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_1002011.webp', '["Fuego","Rayo"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Fuego","Rayo"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Viento","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Rayo","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Viento helado","descripcion":"Inflige una pequeña cantidad de Daño de Hielo a todos los aliados.","tipo":"Habilidad","elemento":"Hielo"},{"nombre":"Mirada glacial","descripcion":"Fija un objetivo. Algunas habilidades de Cocolia (ilusión) se lanzarán una vez más sobre el objetivo fijado hasta que la Debilidad de Pica Glacial (ilusión) se rompa o sea derrotada.","tipo":"Habilidad","elemento":"Hielo"}]'::jsonb),
  ('hsr-enemy-5012020', 'honkai-star-rail', 'Poliperro', 'Security Doggo', 'esbirro', 'normal', 'Fabulae', 'Fabulae ampliamente utilizado en el mantenimiento del orden público y la investigación de crímenes para ayudar a las unidades de combate.
El Departamento de Defensa contra Aberrantes fabula en masa este tipo de perros basándose en la serie de novelas infantiles «Los casos de Lassio, el perro increíble», lo que garantiza que cada can fabulado sea leal y deteste profundamente la maldad.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_5012020.webp', '["Hielo","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, null, '[{"nombre":"Detención","descripcion":"Inflige Daño Físico a un aliado.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Guardia","descripcion":"Aplica Lealtad a un enemigo. Cuando el objetivo con Lealtad recibe un ataque, Poliperro transfiere el daño de dicho ataque a sí mismo y genera Chiste para los aliados.","tipo":"Habilidad","elemento":null}]'::jsonb),
  ('hsr-enemy-5012120', 'honkai-star-rail', 'Pom-Pom de Aleación', '"Alloy Pommy"', 'esbirro', 'normal', null, 'Mecatrones que ofrecen servicios de seguridad y limpieza en el Festival Star Rail.
