  ('hsr-enemy-3021030', 'honkai-star-rail', 'Punta de Lanza', '"Speartip"', 'esbirro', 'normal', null, 'Una estatua de La Lanza. La Lanza y El Escudo rodean el Alma de la Belleza y son interdependientes. La Lanza representa el valor para atravesar la oscuridad.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_3021030.webp', '["Físico","Fuego"]'::jsonb, '[{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Físico","Fuego"],"resistencias":[{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Fuego","Imaginario"],"resistencias":[{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Físico","Cuántico"],"resistencias":[{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Fuego","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Arribada del Caballero de la Belleza","descripcion":"Inflige Daño Físico a todos los aliados. Aumenta el daño infligido mientras se encuentra en el estado Alma libre.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Amor de muerte predestinada","descripcion":"Al recibir un golpe letal, inflige Daño Físico a todos los enemigos. Aumenta el daño infligido mientras se encuentra en el estado Alma libre.","tipo":"Talento","elemento":"Físico"}]'::jsonb),
  ('hsr-enemy-4012090', 'honkai-star-rail', 'Punta de los Cien Ojos', 'Twig of Hundred Eyes', 'esbirro', 'normal', null, 'Ojo monocular deambulante de la Divinidad de la Síntesis. No puede capturar imágenes y su función principal es ayudar al ojo principal a polarizar el clima.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4012090.webp', '["Físico","Hielo","Cuántico"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[]'::jsonb),
