  ('hsr-enemy-2022090', 'honkai-star-rail', 'Rama de la Floración', 'Twig of Glorious Blooms', 'esbirro', 'normal', null, 'Una rama del Árbol de la Ambrosía creada por la huella del Cérvido Azabache.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_2022090.webp', '["Hielo","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, '[{"debilidades":["Hielo","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Hielo","Cuántico","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20}]}]'::jsonb, '[{"nombre":"Última primavera","descripcion":"Regenera inmediatamente los PV de todos los enemigos.","tipo":"Habilidad","elemento":null},{"nombre":"Tótem de resurrección","descripcion":"Mientras esté en el campo de batalla, todos los enemigos excepto Rama de la Floración e Inmortal Nuncaocaso regeneran una pequeña cantidad de PV al comenzar el turno.","tipo":"Talento","elemento":null},{"nombre":"Poder nutritivo","descripcion":"Después de que un aliado elimine a esta unidad, obtiene 1 acumulación de Poder nutritivo y el daño infligido aumenta.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-2022100', 'honkai-star-rail', 'Rama del Fruto Abundante', 'Twig of Lavish Fruits', 'esbirro', 'normal', null, 'Una rama del Árbol de la Ambrosía creada por la huella del Cérvido Azabache.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_2022100.webp', '["Fuego","Cuántico","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20}]'::jsonb, null, '[{"nombre":"Primer fruto","descripcion":"Produce Fruto abundante y acumula la energía necesaria para que el Cérvido Azabache de la Abundancia lance Contacto recargado.","tipo":"Habilidad","elemento":null},{"nombre":"Fruto dulce","descripcion":"Produce Fruto abundante y acumula la energía necesaria para que el Cérvido Azabache de la Abundancia lance Contacto recargado.","tipo":"Habilidad","elemento":null},{"nombre":"Poder nutritivo","descripcion":"Después de que un aliado elimine a esta unidad, obtiene 1 acumulación de Poder nutritivo y el daño infligido aumenta.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-2022070', 'honkai-star-rail', 'Rama del Viento Solemne', 'Twig of Wintry Wind', 'esbirro', 'normal', null, 'Una rama del Árbol de la Ambrosía creada por la huella del Cérvido Azabache.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_2022070.webp', '["Hielo","Cuántico","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20}]'::jsonb, '[{"debilidades":["Hielo","Cuántico","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20}]},{"debilidades":["Físico","Hielo","Cuántico"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Cólera","descripcion":"Inflige una pequeña cantidad de Daño de Viento a un aliado y tiene una gran probabilidad de afectarlo con el estado de Cólera. Los objetivos afectados con Cólera no pueden realizar acciones durante cierta cantidad de turnos y atacan a enemigos al azar.","tipo":"Habilidad","elemento":"Viento"},{"nombre":"Tótem de serenidad","descripcion":"Mientras esta unidad esté en el campo de batalla, el daño que los aliados afectados con Cólera infligen a todos los enemigos que no sean Rama del Viento Solemne se reduce en gran medida.","tipo":"Talento","elemento":null},{"nombre":"Poder nutritivo","descripcion":"Después de que un aliado elimine a esta unidad, obtiene 1 acumulación de Poder nutritivo y el daño infligido aumenta.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-4032020', 'honkai-star-rail', 'Recipiente Arruinado', 'Long-Shattered Vessel', 'esbirro', 'normal', null, 'Uno de los clones de Roballamas invocados con el Poder del desastre. Es una lacra alimentada por la voluntad de la aniquilación.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4032020.webp', '["Hielo","Rayo","Cuántico"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Hielo","Rayo","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Hielo","Rayo","Cuántico"],"resistencias":[{"elemento":"Fuego","valor":40},{"elemento":"Viento","valor":40},{"elemento":"Imaginario","valor":40}]},{"debilidades":["Físico","Hielo","Rayo","Cuántico"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Ofrenda conjunta: Nubarrón de la fatalidad","descripcion":"Inflige una pequeña cantidad de Daño Físico a un aliado y a los objetivos adyacentes.","tipo":"Habilidad","elemento":null},{"nombre":"Ofrenda conjunta: Final del destino","descripcion":"Inflige una pequeña cantidad de Daño Físico a todos los aliados. Una parte de los PV reducidos de los objetivos golpeados se convierte en Corrosión.","tipo":"Habilidad","elemento":null},{"nombre":"Reza por mí","descripcion":"Resiste los estados negativos de Control. Cuando Roballamas de la Oscuridad vuelve a lanzar Nubarrón de la fatalidad o Final del destino, si fue invocado por este ataque, ataca junto a Roballamas de la Oscuridad. Luego esta unidad es absorbida por Roballamas de la Oscuridad, con lo que este regenera los PV que fueron convertidos en Enredo agónico y obtiene Poder del desastre.","tipo":"Talento","elemento":null},{"nombre":"Brinda por mí","descripcion":"Tras recibir un golpe letal, si Roballamas de la Oscuridad no tiene 0 acumulaciones de Poder del desastre, esta unidad es invocada de nuevo por él, pero a cambio Roballamas de la Oscuridad pierde 1 acumulación de Poder del desastre y cierta proporción de PV. Cuando Roballamas de la Oscuridad lanza Abandono sin lágrimas, absorbe a esta unidad y regenera los PV que se habían convertido en Enredo agónico.","tipo":"Talento","elemento":null},{"nombre":"Escucha mi canto","descripcion":"Resiste los estados negativos de Control. Cuando Roballamas del Apocalipsis Extraviado está en el estado Salvaguardia firme, reduce el daño recibido por esta unidad. Cuando Roballamas del Apocalipsis Extraviado vuelve a lanzar Nubarrón de la fatalidad o Final del destino, si fue invocado por este ataque, ataca junto a Roballamas del Apocalipsis Extraviado. Luego, esta unidad es absorbida.","tipo":"Talento","elemento":null},{"nombre":"Sacrificio compartido","descripcion":"Si Roballamas del Apocalipsis Extraviado aún está afectado por Rompegrilletes al recibir un golpe letal, vuelve a invocar a esta unidad inmediatamente y pierde 1 acumulación de Poder del desastre a la vez que su Firmeza se reduce.","tipo":"Talento","elemento":null},{"nombre":"Impacto devastador","descripcion":"Inflige una pequeña cantidad de Daño Físico a un aliado.","tipo":"Habilidad","elemento":null},{"nombre":"Retorno a las llamas mortales","descripcion":"Inflige una pequeña cantidad de Daño Físico a un aliado. Después, es absorbido por Roballamas del Apocalipsis Extraviado, y obtiene 1 acumulación de Poder del desastre.","tipo":"Habilidad","elemento":null}]'::jsonb),
  ('hsr-enemy-5012110', 'honkai-star-rail', 'Reportero Osipachi', 'Furbo Journalist', 'esbirro', 'normal', 'Fabulae', 'Un reportero osipachi del Semanario Pachi. Se inventa las noticias de chismes y es un villano a quien le encanta transformarse. De vez en cuando se escabulle del trabajo y se esconde en un rincón, creyendo que así no lo verá nadie.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_5012110.webp', '["Rayo","Cuántico","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20}]'::jsonb, null, '[{"nombre":"Captura","descripcion":"Inflige una pequeña cantidad de Daño Imaginario a un aliado.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"Primer plano desfavorecedor","descripcion":"Al recibir un golpe letal, hace una foto y da una evaluación basada en el daño infligido por el golpe letal, según la cual otorga Exultación como recompensa. Además, genera Chiste para los aliados.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-3002040', 'honkai-star-rail', 'Rufián del Tiempo de la Compañía Teatral de Terrores', 'Dreamjolt Troupe''s Winder Goon', 'esbirro', 'normal', 'Compañía Teatral de Terrores', 'Máquina de servicio de Colonipenal que perdió el control debido a las interferencias emocionales en el paisaje onírico.
Antes era camarero en el Hotel Fantasía y, tras perder el control, sigue cumpliendo con su tarea de anunciar la hora y despierta de la forma más ruda a quienes están soñando.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_3002040.webp', '["Rayo","Cuántico"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Rayo","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Fuego","Viento"],"resistencias":[{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Hielo","Rayo","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Rayo"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Hora de despertarse","descripcion":"Entra en el estado de Recarga. Usa Despertador en la siguiente acción.","tipo":"Habilidad","elemento":null},{"nombre":"Despertador","descripcion":"Hace que todos los enemigos, excepto esta unidad, realicen una acción inmediatamente.","tipo":"Habilidad","elemento":null},{"nombre":"Puño despabilador","descripcion":"Inflige Daño Físico a un aliado.","tipo":"Habilidad","elemento":"Físico"}]'::jsonb),
  ('hsr-enemy-1012010', 'honkai-star-rail', 'Sabueso Autómata', 'Automaton Hound', 'esbirro', 'normal', 'Jarilo-VI', 'Autómata formado a partir de la tecnología que se conserva del viejo mundo. Parece un vehículo de transporte cuyo propósito ya nadie recuerda.
Durante el combate, el Sabueso Autómata proporciona apoyo y regenera PV a los aliados.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_1012010.webp', '["Físico","Rayo"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Físico","Rayo"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Hielo","Cuántico","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20}]},{"debilidades":["Físico","Rayo","Viento"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Rayo","Cuántico"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Rayo","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Hielo","Imaginario"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Físico","Fuego"],"resistencias":[{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Golpe vertical","descripcion":"Inflige una pequeña cantidad de Daño Físico a un aliado.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Módulo de autocuración","descripcion":"Regenera inmediatamente los PV de todos los enemigos.","tipo":"Habilidad","elemento":null}]'::jsonb),
  ('hsr-enemy-8012010', 'honkai-star-rail', 'Saqueador del Vacío', 'Voidranger: Reaver', 'esbirro', 'normal', 'Legión Antimateria', 'Los guerreros que aún no habían muerto fueron reforjados en la Fragua Bélica y obtuvieron el poder de la destrucción. La antimateria llenó sus cuerpos y las partículas negativas vibraron en su interior.
Unidad básica de combate de la Legión Antimateria y la manifestación de la voluntad de destruir. Sigue sus instintos destructivos y posee un ataque muy agresivo.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_8012010.webp', '["Físico","Rayo"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Físico","Rayo"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Hielo"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Rayo"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Cuántico"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Rayo"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Fuego","Cuántico"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Hielo","Imaginario"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]}]'::jsonb, '[{"nombre":"Cuchillo de caza","descripcion":"Inflige una pequeña cantidad de Daño Imaginario a un aliado.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"Salto de remolino","descripcion":"Inflige una pequeña cantidad de Daño Imaginario a un aliado y a los aliados adyacentes.","tipo":"Habilidad","elemento":"Imaginario"}]'::jsonb),
  ('hsr-enemy-4012024', 'honkai-star-rail', 'Seguidor del Héroe', 'Hero''s Follower', 'esbirro', 'normal', 'Titandeudos', 'Un titandeudo esculpido a partir del conflicto e imbuido con la sangre dorada de Nikador. En su interior contiene racionalidad robada. El propósito de su creación no es estudiar el conocimiento universal, sino investigar las brutales artes bélicas y las despiadadas leyes de la supervivencia, propagando así una locura que se pretende hacer pasar por filosofía.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4012020.webp', '["Fuego","Hielo","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, null, '[{"nombre":"Invisibilidad","descripcion":"Entra en el estado de Invisibilidad y, en la siguiente acción, lanza Rule Breaker.","tipo":"Habilidad","elemento":null},{"nombre":"Rule Breaker","descripcion":"Inflige Daño Físico a un aliado.","tipo":"Habilidad","elemento":"Físico"}]'::jsonb),
  ('hsr-enemy-4052011', 'honkai-star-rail', 'Sirena Alucinógena', 'Hallucinogenic Mermaid', 'esbirro', 'normal', null, 'Aquellos que enloquecen por el canto de las sirenas pierden la cordura en el instante en que se lanzan al océano y se convierten en peones de ellas.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4052010.webp', '["Físico","Rayo","Viento"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[{"nombre":"Vestido ondulante del mar","descripcion":"Inflige una pequeña cantidad de Daño de Hielo a todos los aliados.","tipo":"Habilidad","elemento":"Hielo"},{"nombre":"La soledad insoportable del río Estigia","descripcion":"Al recibir un golpe letal, inflige una gran cantidad de Daño de Hielo a todos los enemigos y los afecta con el estado de Erosión gélida.","tipo":"Talento","elemento":"Hielo"}]'::jsonb),
  ('hsr-enemy-4052010', 'honkai-star-rail', 'Sirvienta de las Mareas', 'Servant of Tides', 'esbirro', 'normal', 'Sirena abisal', 'Las hijas del mar, con sus cuerpos y almas corroídos por el pecado de la Destrucción, cantan y bailan por la oscuridad que se avecina como figuras huecas y retorcidas.
La marea oscura remanente fluye desde eras pasadas hacia el presente y cae en las olas de este mundo.
¡Oh, hermosas y leales olas!, se bañaron en el lodo que desborda la copa del amo y sus vestidos inmaculados quedaron manchados por la locura...
Flotan sin dirección entre el flujo de la vida y la muerte, sin un solo momento de paz.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4052010.webp', '["Físico","Rayo","Viento"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[{"nombre":"Vestido ondulante del mar","descripcion":"Inflige una pequeña cantidad de Daño de Hielo a todos los aliados. Mientras está en el estado Disfrute destructivo, aplica Calor de la marea oscura a los aliados atacados, lo que hace que una parte del daño infligido se reciba en forma de Daño con el tiempo durante cierta cantidad de turnos.","tipo":"Habilidad","elemento":"Hielo"},{"nombre":"La soledad insoportable del río Estigia","descripcion":"Al recibir un golpe letal, inflige Daño de Hielo a todos los enemigos.","tipo":"Talento","elemento":"Hielo"},{"nombre":"Descanso en el agua","descripcion":"Después de recibir cierta cantidad de ataques con el ATQ básico, la habilidad básica, la habilidad definitiva o la habilidad de mnemoduende, su acción se adelanta. Cuando se encuentra en el estado de Disfrute destructivo, se reduce la cantidad de ataques necesarios para activar la Acción adelantada.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-3002024', 'honkai-star-rail', 'Skott Avaricioso', 'Greedy Skott', 'esbirro', 'normal', null, 'Skott, que reunió todos los recursos de filmación para convertirse en el protagonista más grande de todos los protagonistas. Busca vengarse {F#de la}{M#del} Trazacaminos con mil apariencias distintas después de que un Servant dispersara su consciencia y su alma.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_3002024.webp', '["Fuego","Rayo","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, null, '[{"nombre":"Regalo del lobo","descripcion":"Los aliados recuperan pts. de habilidad básica. Esta habilidad solo se puede usar en el estado Burla.","tipo":"Habilidad","elemento":null},{"nombre":"Burla del lobo","descripcion":"Se reducen los pts. de habilidad básica de los aliados. Esta habilidad solo se puede usar en el estado Enloquecimiento.","tipo":"Habilidad","elemento":null},{"nombre":"El lobo solitario nunca se rinde","descripcion":"Cambia el estado Burla al estado Enloquecimiento.","tipo":"Habilidad","elemento":null},{"nombre":"La huida del lobo","descripcion":"Tras recibir un ataque, cambia el estado Enloquecimiento al estado Burla. Cuando se encuentra en el estado Burla, no cambia tras recibir un ataque.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-3002025', 'honkai-star-rail', 'Skott Avaricioso (contaminado)', 'Greedy Skott (Corrupted)', 'esbirro', 'normal', null, 'Skott, que reunió todos los recursos de filmación para convertirse en el protagonista más grande de todos los protagonistas. Busca vengarse {F#de la}{M#del} Trazacaminos con mil apariencias distintas después de que un Servant dispersara su consciencia y su alma.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_3002024.webp', '["Fuego","Rayo","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, null, '[{"nombre":"Regalo del lobo","descripcion":"Los aliados recuperan pts. de habilidad básica. Esta habilidad solo se puede usar en el estado Burla.","tipo":"Habilidad","elemento":null},{"nombre":"Burla del lobo","descripcion":"Se reducen los pts. de habilidad básica de los aliados. Esta habilidad solo se puede usar en el estado Enloquecimiento.","tipo":"Habilidad","elemento":null},{"nombre":"El lobo solitario nunca se rinde","descripcion":"Cambia el estado Burla al estado Enloquecimiento.","tipo":"Habilidad","elemento":null},{"nombre":"La huida del lobo","descripcion":"Tras recibir un ataque, cambia el estado Enloquecimiento al estado Burla. Cuando se encuentra en el estado Burla, no cambia tras recibir un ataque.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-3002015', 'honkai-star-rail', 'Skott Celoso', 'Envious Skott', 'esbirro', 'normal', null, 'Skott, que reunió todos los recursos de filmación para convertirse en el protagonista más grande de todos los protagonistas. Busca vengarse {F#de la}{M#del} Trazacaminos con mil apariencias distintas después de que un Servant dispersara su consciencia y su alma.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_3002015.webp', '["Hielo","Rayo","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, null, '[{"nombre":"Compasión del lobo","descripcion":"Recupera energía para un aliado. Esta habilidad solo se puede usar en el estado de Burla.","tipo":"Habilidad","elemento":null},{"nombre":"Maldición del lobo","descripcion":"Inflige una pequeña cantidad de Daño Cuántico a todos los aliados y reduce la energía de todos los aliados. Esta habilidad solo se puede usar en el estado de Enloquecimiento.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"El lobo solitario nunca se rinde","descripcion":"Cambia el estado Burla al estado Enloquecimiento.","tipo":"Habilidad","elemento":null},{"nombre":"La huida del lobo","descripcion":"Tras recibir un ataque, cambia el estado Enloquecimiento al estado Burla. Cuando se encuentra en el estado Burla, no cambia tras recibir un ataque.","tipo":"Talento","elemento":null}]'::jsonb),
