  ('hsr-enemy-3002014', 'honkai-star-rail', 'Skott: Unidad de Producción en Masa', 'Skott: Batch Produced', 'esbirro', 'normal', null, 'Skott dividido en múltiples cuerpos por el poder de Assassin. Cada Unidad de Producción en Masa tiene el mismo poder que el prototipo original.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_3002014.webp', '["Hielo","Rayo","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, null, '[{"nombre":"Compasión del lobo","descripcion":"Recupera energía para un aliado. Esta habilidad solo se puede usar en el estado de Compasión.","tipo":"Habilidad","elemento":null},{"nombre":"Maldición del lobo","descripcion":"Inflige una pequeña cantidad de Daño Cuántico a todos los aliados y reduce la energía de todos los objetivos. Esta habilidad solo se puede usar en el estado de Maldición.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"El lobo solitario nunca se rinde","descripcion":"Cambia el estado Compasión al estado Maldición.","tipo":"Habilidad","elemento":null},{"nombre":"La huida del lobo solitario","descripcion":"Tras recibir un ataque, cambia el estado Compasión al estado Maldición, o viceversa.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-1002040', 'honkai-star-rail', 'Soldado Crinargenta', 'Silvermane Soldier', 'esbirro', 'normal', 'Jarilo-VI', 'Soldado de la Guardia Crinargenta de Belobog. Su misión es estar en la primera línea cuando se carga contra el enemigo.
