  ('hsr-enemy-2032020', 'honkai-star-rail', 'Soldado Lobo Devoralunas', 'Eclipse Wolftrooper', 'esbirro', 'normal', 'El Luofu de Xianzhou', 'Soldado borisin de la manada Devoralunas. Su voraz apetito por la sangre y la carne de sus enemigos es tristemente famoso.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_2032020.webp', '["Físico","Viento"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Físico","Viento"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Hielo","Rayo","Viento"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Viento","Cuántico","Imaginario"],"resistencias":[{"elemento":"Fuego","valor":40},{"elemento":"Hielo","valor":40},{"elemento":"Rayo","valor":40}]}]'::jsonb, '[{"nombre":"Mordisco","descripcion":"Inflige Daño Físico a un aliado. Si está afectado por Locura lunar, regenera PV después de atacar al objetivo aliado.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Deglución lupina","descripcion":"Después de que un enemigo ataque, aplica 1 acumulación de Sed de sangre a los enemigos que puedan entrar en el estado de Locura lunar. Cuando Sed de sangre alcanza cierta cantidad de acumulaciones, el enemigo entra en el estado de Locura lunar.\nEn el orden de acción aparece una cuenta regresiva de Locura lunar. Cuando comienza el turno de la cuenta regresiva, se disipa el estado de Locura lunar de todos los enemigos.","tipo":"Habilidad","elemento":"Físico"}]'::jsonb),
  ('hsr-enemy-2032010', 'honkai-star-rail', 'Soldado Lobo Garranegra', 'Sableclaw Wolftrooper', 'esbirro', 'normal', 'El Luofu de Xianzhou', 'Soldado borisin de la manada Garranegra. Es especialista en atacar y asesinar silenciosamente a sus presas.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_2032010.webp', '["Fuego","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, '[{"debilidades":["Fuego","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Fuego","Viento","Cuántico","Imaginario"],"resistencias":[{"elemento":"Físico","valor":40},{"elemento":"Hielo","valor":40},{"elemento":"Rayo","valor":40}]}]'::jsonb, '[{"nombre":"Masacre","descripcion":"Inflige una pequeña cantidad de Daño Físico a un aliado y a los objetivos adyacentes. Si se encuentra en el estado de Locura lunar, hay una gran probabilidad de aplicar Sangrado al objetivo.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Deglución lupina","descripcion":"Después de que un enemigo ataque, aplica 1 acumulación de Sed de sangre a los enemigos que puedan entrar en el estado de Locura lunar. Cuando Sed de sangre alcanza cierta cantidad de acumulaciones, el enemigo entra en el estado de Locura lunar.\nEn el orden de acción aparece una cuenta regresiva de Locura lunar. Cuando comienza el turno de la cuenta regresiva, se disipa el estado de Locura lunar de todos los enemigos.","tipo":"Habilidad","elemento":"Físico"}]'::jsonb),
  ('hsr-enemy-2022010', 'honkai-star-rail', 'Soldado Poseído por Mara', 'Mara-Struck Soldier', 'esbirro', 'normal', 'El Luofu de Xianzhou', 'Soldado de Xianzhou que por algún motivo desconocido cayó presa de la locura. Su cuerpo sigue creciendo y mutando, pero hace tiempo que perdió la forma humana. De estas personas afectadas por la vida sin fin se dice que están poseídas por Mara.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_2022010.webp', '["Fuego","Hielo","Cuántico"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":40},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Fuego","Hielo","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":40},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Hielo","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Fuego","Cuántico"],"resistencias":[{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Fuego","Hielo","Rayo","Viento","Cuántico","Imaginario"],"resistencias":[]},{"debilidades":["Fuego","Cuántico","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":40}]}]'::jsonb, '[{"nombre":"Viento desalmado","descripcion":"Inflige una pequeña cantidad de Daño de Viento a un aliado y tiene una gran probabilidad de afectarlo con Intemperie.","tipo":"Habilidad","elemento":"Viento"},{"nombre":"Rejuvenecimiento","descripcion":"Al recibir un golpe letal, regenera una cantidad de PV. Este efecto no tiene límite de tiempo, pero se puede eliminar y solo se puede activar 1 vez por batalla.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-1022020', 'honkai-star-rail', 'Sombra de la Incineración', 'Incineration Shadewalker', 'esbirro', 'normal', 'Monstruos del Fragmentum', 'Sombras que vagan por el Fragmentum tras la llegada del Hielo Eterno y que imitan la silueta de Guardias Crinargenta de una forma retorcida. Llevan las mismas armaduras uniformadas que los guardias de Belobog, pero su cara es una lámina de ascuas sin rostro.
Las Sombras de la Incineración blanden su hacha ardiente y queman a sus enemigos.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_1022020.webp', '["Hielo","Viento","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":40},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, '[{"debilidades":["Hielo","Viento","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":40},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Hielo","Rayo","Viento","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":40},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Físico","Hielo","Viento"],"resistencias":[{"elemento":"Fuego","valor":40},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Hielo","Rayo","Viento"],"resistencias":[{"elemento":"Fuego","valor":40},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Hielo","Imaginario"],"resistencias":[{"elemento":"Fuego","valor":40},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Hielo","Rayo","Viento"],"resistencias":[{"elemento":"Fuego","valor":40},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Fuego","Hielo","Rayo","Viento","Cuántico","Imaginario"],"resistencias":[]}]'::jsonb, '[{"nombre":"Impacto ardiente","descripcion":"Inflige Daño de Fuego a un aliado y tiene una gran probabilidad de causar Quemadura a ese aliado.","tipo":"Habilidad","elemento":"Fuego"}]'::jsonb),
  ('hsr-enemy-4032027', 'honkai-star-rail', 'Sombra del Odio', 'Shadow of "Hatred"', 'esbirro', 'normal', null, 'El odio calculado por NeiKos496 en sus interminables extrapolaciones nutre la Destrucción que silencia el mar de estrellas. Este sentimiento desborda su cáscara perfecta, y deja tras de sí el eco de una maldad suprema.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4032020.webp', '["Físico","Hielo","Rayo","Cuántico"]'::jsonb, '[{"elemento":"Fuego","valor":40},{"elemento":"Viento","valor":40},{"elemento":"Imaginario","valor":40}]'::jsonb, null, '[{"nombre":"Que los deseos vacíos no se desvanezcan","descripcion":"Inflige una pequeña cantidad de Daño Físico a todos los aliados.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Que la sangre dorada no se derrame en vano","descripcion":"Por cada Sombra del Odio creada, Khaslana pierde cierta proporción de PV.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-1022010', 'honkai-star-rail', 'Sombra del Siempreinvierno', 'Everwinter Shadewalker', 'esbirro', 'normal', 'Monstruos del Fragmentum', 'Sombras que vagan por el Fragmentum tras la llegada del Hielo Eterno y que imitan la silueta de Guardias Crinargenta de una forma retorcida. Llevan las mismas armaduras uniformadas que los guardias de Belobog, pero su cara es una lámina de hielo sin rostro.
Las Sombras del Siempreinvierno blanden su hacha gélida y ralentizan a sus enemigos.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_1022010.webp', '["Físico","Fuego","Cuántico"]'::jsonb, '[{"elemento":"Hielo","valor":40},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Físico","Fuego","Cuántico"],"resistencias":[{"elemento":"Hielo","valor":40},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Fuego","Rayo","Cuántico"],"resistencias":[{"elemento":"Hielo","valor":40},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Fuego","Rayo"],"resistencias":[{"elemento":"Hielo","valor":40},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Rayo","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":40},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Cuántico"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":40},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":40},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Impacto helado","descripcion":"Inflige Daño de Hielo a un aliado y retrasa la acción de ese aliado.","tipo":"Habilidad","elemento":"Hielo"}]'::jsonb),
  ('hsr-enemy-3002010', 'honkai-star-rail', 'Sr. Pantallarredonda de la Compañía Teatral de Terrores', 'Dreamjolt Troupe''s Mr. Domescreen', 'esbirro', 'normal', 'Compañía Teatral de Terrores', 'Máquina de servicio de Colonipenal que perdió el control debido a las interferencias emocionales en el paisaje onírico.
Era animador en programas de televisión y, tras perder el control, continúa interpretando sus papeles cambiantes para sorprender o asustar a la audiencia.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_3002010.webp', '["Hielo","Rayo","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, null, '[{"nombre":"Programa de variedades sorpresa","descripcion":"Recupera energía para un aliado. Esta habilidad solo se puede usar en el estado Canal sorpresa.","tipo":"Habilidad","elemento":null},{"nombre":"Retransmisión aterradora","descripcion":"Inflige una pequeña cantidad de Daño Cuántico a todos los aliados y reduce la energía de todos los objetivos. Esta habilidad solo se puede usar en el estado Canal aterrador.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"Cambio de canal","descripcion":"Cambia el estado Canal sorpresa al estado Canal aterrador.","tipo":"Habilidad","elemento":null},{"nombre":"Interferencia entre canales","descripcion":"Tras recibir un ataque, cambia el estado Canal sorpresa al estado Canal aterrador, o viceversa.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-8002010', 'honkai-star-rail', 'Tejedora Imaginaria', 'Imaginary Weaver', 'esbirro', 'normal', 'Monstruos del Fragmentum', 'Ser extraño que no es de este mundo. Llegó hasta aquí después de atravesar el velo desde el otro lado del oscuro cielo estrellado. Su cuerpo es como una rama enfermiza que se asoma a la realidad y la transforma según su voluntad utilizando un poder imaginario.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_8002010.webp', '["Físico","Rayo","Cuántico"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Físico","Rayo","Cuántico"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Fuego","Hielo","Rayo","Viento","Cuántico","Imaginario"],"resistencias":[]},{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Hielo","Rayo"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Rayo del himno","descripcion":"Inflige una pequeña cantidad de Daño Imaginario a un aliado.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"Himno explosivo","descripcion":"Inflige una gran cantidad de Daño Imaginario a un aliado.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"Himno reverberante","descripcion":"Inflige Daño Imaginario a un aliado y a los aliados adyacentes y entra en el estado de Posición defensiva. En la siguiente acción, lanza Himno explosivo y aumenta en gran medida el daño que inflige.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"Armadura imaginaria","descripcion":"Se reduce el daño que infligen los tipos de daño que no sean del tipo de su Debilidad.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-1002050', 'honkai-star-rail', 'Tirador Crinargenta', 'Silvermane Gunner', 'esbirro', 'normal', 'Jarilo-VI', 'Tirador de la Guardia Crinargenta de Belobog. Se encarga de disparar a los enemigos.
Los disparos de los Tiradores Crinargenta causan Sangrado a tu equipo durante el combate.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_1002050.webp', '["Físico","Hielo"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Físico","Hielo"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Hielo","Cuántico","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20}]},{"debilidades":["Físico","Rayo","Viento"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Hielo"],"resistencias":[]},{"debilidades":["Físico","Hielo","Rayo"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Fuego","Hielo","Rayo","Viento","Cuántico","Imaginario"],"resistencias":[]},{"debilidades":["Físico","Fuego","Hielo"],"resistencias":[{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Cuántico"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Cuántico"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Hielo"],"resistencias"