  ('hsr-enemy-8032030', 'honkai-star-rail', 'Todo o Nada', '"All or Nothing"', 'esbirro', 'normal', null, 'Un dado de juego que se transformó a partir de Aventurino de las Estratagemas. Decide el destino de quienes participan en la apuesta.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_8032030.webp', '["Físico","Hielo","Rayo","Viento"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[{"nombre":"Fortuna impredecible","descripcion":"Inmune al daño. Cuando recibe un ataque de un objetivo que ha entrado a la apuesta, otorga 1 número al azar (entre 1 y 6) al objetivo.","tipo":"Talento","elemento":null},{"nombre":"Castigo al perdedor","descripcion":"Se autodestruye e inflige Daño Imaginario a Aventurino de las Estratagemas.","tipo":"Habilidad","elemento":null},{"nombre":"Nunca descubierto","descripcion":"Cuando recibe un ataque de un objetivo que ha entrado a la apuesta, la probabilidad de la apuesta se duplica.","tipo":"Talento","elemento":null},{"nombre":"Apuesta","descripcion":"Tras ser eliminado, sus puntos se suman a los de los aliados. Al mismo tiempo, reduce la Firmeza de Lanzador de Dados Audaz y pierde una cantidad determinada de PV.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-8032034', 'honkai-star-rail', 'Todo o Nada: Doble Fortuna', '"All or Nothing: Double Fortune"', 'esbirro', 'normal', null, 'Un dado de juego que se transformó a partir del Lanzador de Dados Audaz. Decide el destino de quienes participan en la apuesta.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_8032034.webp', '["Físico","Hielo","Rayo","Viento"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[{"nombre":"Buena fortuna temporal","descripcion":"Al realizar una acción, abandona la batalla.","tipo":"Habilidad","elemento":null},{"nombre":"Apuesta doble","descripcion":"Tras ser eliminado, los puntos de los aliados se duplican. Al mismo tiempo, reduce la Firmeza del Lanzador de Dados Audaz y pierde una cantidad determinada de PV.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-3012030', 'honkai-star-rail', 'Tumba del Sueño Eterno', 'Sombrous Sepulcher', 'esbirro', 'normal', null, 'Las existencias fragmentadas son símbolos de un cierre definitivo. A través de la vastedad etérea, los espíritus observan el reino mortal, con sus ojos reflejando las marcas del olvido y la separación.
Almas inocentes descansan dentro de la Tumba del Sueño Eterno. Derrótala para despertarlas.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_3012030.webp', '["Fuego","Viento","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, null, '[{"nombre":"Despertar de un sueño silencioso","descripcion":"Cuando la Tumba del Sueño Eterno recibe un golpe letal, se disipa Sueño hasta el fin en el objetivo aliado correspondiente y este aliado regenera PV y recupera energía.","tipo":"Habilidad","elemento":null},{"nombre":"Paso del tiempo","descripcion":"La Tumba del Sueño Eterno no realiza ninguna acción.","tipo":"Habilidad","elemento":null},{"nombre":"Continuación eterna","descripcion":"Tumba del Sueño Eterno tiene una cantidad fija de barras de PV. Cada vez que recibe un ataque, se rompe su Debilidad o recibe Daño con el tiempo, se consume 1 barra de PV.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-1002020', 'honkai-star-rail', 'Vagabundo', 'Vagrant', 'esbirro', 'normal', 'Jarilo-VI', 'Algunos habitantes del Bajomundo desesperados por sobrevivir se adentran en el Fragmentum para buscar cualquier cosa de utilidad. Las antiguas máquinas que desentierran se han convertido en sus mejores aliadas.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_1002020.webp', '["Fuego","Hielo","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, '[{"debilidades":["Fuego","Hielo","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Fuego","Hielo","Cuántico","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20}]},{"debilidades":["Físico","Rayo","Viento"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Rayo","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Fuego","Imaginario"],"resistencias":[{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Fuego","Imaginario"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]}]'::jsonb, '[{"nombre":"Palazo","descripcion":"Inflige una pequeña cantidad de Daño Físico a un aliado.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Motivación","descripcion":"Aumenta el ATQ de un enemigo determinado, que también realiza una acción inmediatamente.","tipo":"Habilidad","elemento":null}]'::jsonb),
  ('hsr-enemy-5012010', 'honkai-star-rail', 'Varita Automágica', 'Autonomous Wand', 'esbirro', 'normal', 'Fabulae', 'Arma fabularia del Grupo de Chicas Mágicas capaz de moverse gracias a los deseos de las jóvenes.
Se carga con el canto y reproduce algunos hechizos de transformación.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_5012010.webp', '["Físico","Imaginario"]'::jsonb, '[{"elemento":"Fuego","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, null, '[{"nombre":"Bala mágica crepitante","descripcion":"Inflige Daño Cuántico a un aliado.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"Hechizo de felicidad","descripcion":"Activa aleatoriamente uno de los siguientes efectos: aumenta el ATQ de esta unidad, adelanta la acción de todos los enemigos o gran probabilidad de aplicar Reverberación potente a todos los enemigos excepto a esta unidad.","tipo":"Habilidad","elemento":null},{"nombre":"Magia de la sonrisa","descripcion":"Cuando esta unidad recibe un ataque por primera vez, los aliados obtienen Chiste. Lanza Hechizo de felicidad.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-3002020', 'honkai-star-rail', 'Vendefortunas de la Compañía Teatral de Terrores', 'Dreamjolt Troupe''s Fortune Seller', 'esbirro', 'normal', 'Compañía Teatral de Terrores', 'Máquina de servicio de Colonipenal que perdió el control debido a las interferencias emocionales en el paisaje onírico.
Era un robot que sorteaba premios para sorprender agradablemente a los huéspedes. Incluso después de perder el control, sigue ofreciendo todo tipo de regalos y espera probar la buena fortuna de los huéspedes sacrificándose a sí mismo.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_3002020.webp', '["Fuego","Viento"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Fuego","Viento"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Hielo","Viento"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Hielo","Viento"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Calentamiento para el sorteo","descripcion":"Inflige Daño Físico a un aliado.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Bolsa de premios de Terrores","descripcion":"Al recibir un golpe letal del tipo de ataque especificado, se activan distintos efectos según el tipo de ataque. Si recibe a la vez ataques de múltiples tipos, se activarán los efectos en el siguiente orden de prioridad: ¡Pierdes el 50/50!, ¡Llegaste al pity!, ¡Aquí está el premio!","tipo":"Habilidad","elemento":null},{"nombre":"¡Pierdes el 50/50!","descripcion":"Tras recibir un golpe letal por un ataque básico o Daño con el tiempo, recupera pts. de habilidad básica para los aliados.","tipo":"Habilidad","elemento":null},{"nombre":"¡Llegaste al pity!","descripcion":"Tras recibir un golpe letal de una habilidad básica, una habilidad de mnemoduende o un ataque adicional, recupera energía para todos los aliados.","tipo":"Habilidad","elemento":null},{"nombre":"¡Aquí está el premio!","descripcion":"Tras recibir un golpe letal por una habilidad definitiva, recupera energía y pts. de habilidad básica para todos los aliados.","tipo":"Habilidad","elemento":null}]'::jsonb)
on conflict (id) do update
  set game_id = excluded.game_id,
      name = excluded.name,
      name_en = excluded.name_en,
      category = excluded.category,
      rank = excluded.rank,
      faction = excluded.faction,
      description = excluded.description,
      image_url = excluded.image_url,
      weaknesses = excluded.weaknesses,
      resistances = excluded.resistances,
      variants = excluded.variants,
      skills = excluded.skills,
      updated_at = now();

-- Comprobacion
select category, rank, count(*) as enemigos, count(image_url) as con_icono
from public.enemies
where game_id = 'honkai-star-rail'
group by category, rank
order by category, rank;
